import { useEffect, useRef, useState } from 'react';
import { isTavernGenerating } from '../utils/fillTavernInput';
import { BookOpen, School, MapPin, User, FileText, ChevronDown, X } from 'lucide-react';
import {
  checkMvuPatchResult,
  describeMvuChanges,
  diffMvu,
  displayMvuValue,
  hasMvuStart,
  extractFinalMvuBlock,
  inspectMvuCode,
  UpdateNotice,
} from '../utils/mvuUpdates';

type Batch = {
  id: number;
  floor: number;
  at: number;
  notices: UpdateNotice[];
  error?: string;
  code: string;
  historical?: boolean;
};
const RECORD_PATH = '校园APP.MVU更新记录';
function saveBatch(batch: Batch) {
  void updateVariablesWith(
    variables => {
      const records = _.get(variables, RECORD_PATH, []) as Batch[];
      _.set(variables, RECORD_PATH, [batch, ...records.filter(item => item.floor !== batch.floor)].slice(0, 12));
      return variables;
    },
    { type: 'chat' },
  ).catch((reason: unknown) => console.warn('[校园平板] 更新记录保存失败', reason));
}
const icons = { 建筑: School, 地点: MapPin, 人物: User, 校规: BookOpen };

export function MvuUpdateNotice() {
  const [updating, setUpdating] = useState(false);
  const [batches, setBatches] = useState<Batch[]>([]);
  const [editor, setEditor] = useState<{ floor: number; original: string; value: string } | null>(null);
  const [feedback, setFeedback] = useState('');
  const [saving, setSaving] = useState(false);
  const processing = useRef(false);
  const version = useRef(0);
  const activeFloor = useRef(-1);

  useEffect(() => {
    let disposed = false;
    let timer: number | undefined;
    let code = '';
    let commands: Mvu.CommandInfo[] = [];
    let before: Record<string, unknown> = {};
    let ended = false;
    let streamText = '';
    let streamStarted = false;
    let generating = isTavernGenerating();
    let snapshotSignature = '';
    let refreshTimer: number | undefined;
    let mvuReady = false;
    let pendingResult: { notices: UpdateNotice[]; error?: string; floor: number; code: string } | null = null;
    const subscriptions: EventOnReturn[] = [];
    const floor = () => {
      try {
        return getLastMessageId();
      } catch {
        return -1;
      }
    };
    const record = (notices: UpdateNotice[], error?: string) => {
      const resultCode = code;
      const resultFloor = activeFloor.current;
      const result = { notices, error, floor: resultFloor, code: resultCode };
      if (generating) {
        pendingResult = result;
        return;
      }
      snapshotSignature = '';
      setUpdating(false);
      window.clearTimeout(timer);
      const batch = { id: Date.now(), floor: resultFloor, at: Date.now(), notices, error, code: resultCode };
      saveBatch(batch);
      setBatches(previous => [batch, ...previous.filter(item => item.floor !== batch.floor)].slice(0, 12));
    };
    const readHistory = () => {
      if (!mvuReady || disposed || generating || processing.current || isTavernGenerating()) return;
      if (floor() < 0) return;
      const messages = getChatMessages(`0-${floor()}`);
      const stored = _.get(getVariables({ type: 'chat' }), RECORD_PATH, []) as Batch[];
      const validStored = Array.isArray(stored)
        ? stored.filter(batch =>
            messages.some(
              message =>
                message.message_id === batch.floor &&
                message.role === 'assistant' &&
                inspectMvuCode(message.message).code === batch.code,
            ),
          )
        : [];
      const recovered: Batch[] = [];
      const signatures: unknown[] = [];
      for (const message of messages) {
        if (message.role !== 'assistant') continue;
        const inspected = inspectMvuCode(extractFinalMvuBlock(message.message));
        if (!inspected.expected && !hasMvuStart(message.message)) continue;
        const current = Mvu.getMvuData({ type: 'message', message_id: message.message_id });
        const previous =
          message.message_id > 0 ? Mvu.getMvuData({ type: 'message', message_id: message.message_id - 1 }) : undefined;
        const comparable = !!current?.stat_data && !!previous?.stat_data;
        signatures.push([message.message_id, inspected.code, current?.stat_data, previous?.stat_data]);
        recovered.unshift({
          id: message.message_id,
          floor: message.message_id,
          at: 0,
          historical: true,
          code: inspected.code,
          notices: comparable ? describeMvuChanges(diffMvu(previous.stat_data, current.stat_data)) : [],
          error:
            inspected.error ||
            (current?.stat_data ? checkMvuPatchResult(message.message, current.stat_data) : undefined) ||
            (!comparable ? '此楼层缺少可对比的变量快照，只能回读更新代码，无法确认写入。' : undefined),
        });
      }
      const signature = JSON.stringify(signatures);
      if (signature === snapshotSignature) return;
      snapshotSignature = signature;
      setBatches(existing => {
        const next = recovered
          .map(batch => {
            const prior =
              existing.find(item => item.floor === batch.floor) || validStored.find(item => item.floor === batch.floor);
            return { ...batch, id: prior?.id ?? batch.id, at: prior?.at || Date.now(), historical: false };
          })
          .slice(0, 12);
        return _.isEqual(existing, next) ? existing : next;
      });
      const latest = recovered[0];
      if (latest && latest.floor === activeFloor.current && !latest.error) {
        ended = true;
        setUpdating(false);
        window.clearTimeout(timer);
      }
    };
    const refresh = () => {
      window.clearTimeout(refreshTimer);
      refreshTimer = window.setTimeout(() => {
        try {
          readHistory();
        } catch (reason) {
          console.warn('[校园平板] MVU 快照同步失败', reason);
        }
      }, 150);
    };
    const polling = window.setInterval(refresh, 1000);
    [
      tavern_events.MESSAGE_UPDATED,
      tavern_events.MESSAGE_EDITED,
      tavern_events.MESSAGE_SWIPED,
      tavern_events.MESSAGE_DELETED,
      tavern_events.CHARACTER_MESSAGE_RENDERED,
    ].forEach(event => subscriptions.push(eventOn(event, refresh)));
    const observeStream = (text: string) => {
      if (processing.current || !generating) return;
      streamText = text;
    };
    const finalizeGeneration = (messageId: number) => {
      generating = false;
      window.clearTimeout(timer);
      const message = getChatMessages(messageId)[0];
      const finalCode = extractFinalMvuBlock(message?.message || streamText);
      const inspected = inspectMvuCode(finalCode);
      if (!inspected.expected && !inspected.error) {
        pendingResult = null;
        window.clearTimeout(timer);
        setUpdating(false);
        return;
      }
      if (pendingResult) {
        const pending = pendingResult;
        pendingResult = null;
        code = inspected.code;
        activeFloor.current = messageId;
        if (inspected.error) {
          record([], inspected.error);
          return;
        }
        const finalData = Mvu.getMvuData({ type: 'message', message_id: messageId });
        const error = finalData?.stat_data ? checkMvuPatchResult(code, finalData.stat_data) : pending.error;
        record(pending.notices, error);
        return;
      }
      activeFloor.current = messageId;
      code = inspected.code;
      if (inspected.error) {
        record([], inspected.error);
        return;
      }
      if (ended) return;
      streamStarted = true;
      setUpdating(true);
      window.clearTimeout(timer);
      timer = window.setTimeout(() => record([], '生成已结束，但尚未收到 MVU 完成确认，请检查更新代码。'), 45000);
    };
    void (async () => {
      await waitGlobalInitialized('Mvu');
      if (disposed) return;
      mvuReady = true;
      subscriptions.push(
        eventOn(Mvu.events.VARIABLE_UPDATE_STARTED, variables => {
          if (processing.current) return;
          before = _.cloneDeep(variables.stat_data);
          activeFloor.current = floor();
          ended = false;
          commands = [];
          code = '';
          setUpdating(true);
          window.clearTimeout(timer);
          if (!generating) {
            timer = window.setTimeout(
              () => record([], '更新等待超时，尚未确认写入。请检查最新回复，可重新生成或手动修正。'),
              45000,
            );
          }
        }),
      );
      subscriptions.push(
        eventOn(Mvu.events.COMMAND_PARSED, (_variables, parsed, content) => {
          if (processing.current) return;
          commands = _.cloneDeep(parsed);
          code = inspectMvuCode(extractFinalMvuBlock(content)).code;
        }),
      );
      subscriptions.push(
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, old) => {
          if (processing.current) return;
          ended = true;
          activeFloor.current = floor();
          const finalMessage = getChatMessages(activeFloor.current)[0]?.message || streamText;
          const finalCode = extractFinalMvuBlock(finalMessage);
          if (finalCode) code = inspectMvuCode(finalCode).code;
          const notices = describeMvuChanges(diffMvu(old?.stat_data || before, variables.stat_data));
          const error =
            checkMvuPatchResult(code, variables.stat_data) ||
            (!notices.length && commands.length === 0 && inspectMvuCode(code).expected
              ? '回复含更新代码，但 MVU 未解析到可执行指令，请检查框架版本和输出格式。'
              : undefined);
          if (generating) {
            pendingResult = { notices, error, floor: activeFloor.current, code };
            setUpdating(true);
          } else if (streamStarted || inspectMvuCode(code).expected || error) {
            record(notices, error);
          } else {
            setUpdating(false);
            window.clearTimeout(timer);
          }
          refresh();
        }),
      );
      readHistory();
    })().catch(reason => {
      if (!disposed) {
        activeFloor.current = floor();
        record([], `MVU 连接失败：${String(reason)}`);
      }
    });
    subscriptions.push(
      eventOn(tavern_events.GENERATION_STARTED, (type, _options, dryRun) => {
        // Quiet requests do not create a chat floor or run that floor's MVU update.
        if (dryRun || type === 'quiet') return;
        ended = false;
        generating = true;
        pendingResult = null;
        streamText = '';
        streamStarted = false;
        code = '';
        commands = [];
        window.clearTimeout(timer);
        setUpdating(false);
      }),
    );
    subscriptions.push(eventOn(tavern_events.STREAM_TOKEN_RECEIVED, observeStream));
    subscriptions.push(
      eventOn(tavern_events.GENERATION_ENDED, messageId => {
        if (!generating) return;
        const id = Number(messageId);
        if (!Number.isInteger(id) || id < 0) {
          generating = false;
          pendingResult = null;
          setUpdating(false);
          window.clearTimeout(timer);
          refresh();
          return;
        }
        finalizeGeneration(id);
        refresh();
      }),
    );
    subscriptions.push(
      eventOn(tavern_events.GENERATION_STOPPED, () => {
        if (!generating) return;
        generating = false;
        pendingResult = null;
        setUpdating(false);
        if (streamStarted && !ended) record([], '生成已中止，MVU 更新尚未确认完成。');
      }),
    );
    subscriptions.push(
      eventOn(tavern_events.MESSAGE_RECEIVED, messageId => {
        const id = Number(messageId);
        if (!Number.isInteger(id)) return;
        if (processing.current || generating) return;
        const message = getChatMessages(id)[0];
        if (message?.role !== 'assistant') return;
        const result = inspectMvuCode(extractFinalMvuBlock(message.message));
        if (ended && !result.error) return;
        if (result.error) {
          activeFloor.current = id;
          code = result.code;
          streamStarted = true;
          setUpdating(true);
          window.clearTimeout(timer);
          timer = window.setTimeout(() => record([], result.error), 45000);
        } else if (result.expected && !ended) {
          activeFloor.current = id;
          code = result.code;
          setUpdating(true);
          window.clearTimeout(timer);
          timer = window.setTimeout(
            () => record([], '检测到更新指令，但未收到 MVU 完成确认。可在酒馆重 roll，或手动修正。'),
            45000,
          );
        }
      }),
    );
    subscriptions.push(
      eventOn(tavern_events.CHAT_CHANGED, () => {
        version.current++;
        window.clearTimeout(timer);
        setBatches([]);
        setUpdating(false);
        setEditor(null);
        setFeedback('');
        activeFloor.current = -1;
        ended = false;
        generating = false;
        streamStarted = false;
        streamText = '';
        code = '';
        snapshotSignature = '';
        pendingResult = null;
        try {
          readHistory();
        } catch (reason) {
          console.warn('[校园平板] MVU 历史回读失败', reason);
        }
      }),
    );
    return () => {
      disposed = true;
      version.current++;
      window.clearTimeout(timer);
      window.clearTimeout(refreshTimer);
      window.clearInterval(polling);
      subscriptions.forEach(item => item.stop());
    };
  }, []);

  const openEditor = (batch: Batch) => {
    try {
      const message = getChatMessages(batch.floor)[0];
      if (!message || message.role !== 'assistant') throw new Error('该回复已不存在，请在酒馆选择对应楼层。');
      setEditor({
        floor: batch.floor,
        original: message.message,
        value: inspectMvuCode(message.message).code || batch.code || '<JSONPatch>\n[]\n</JSONPatch>',
      });
      setFeedback('');
    } catch (reason) {
      setFeedback(String(reason));
    }
  };
  const apply = async () => {
    if (!editor || saving) return;
    const captured = version.current;
    setSaving(true);
    setFeedback('');
    processing.current = true;
    try {
      const inspected = inspectMvuCode(editor.value);
      if (inspected.error || !inspected.expected)
        throw new Error(inspected.error || '请输入包含有效更新指令的 JSONPatch 标签或 MVU 命令。');
      const current = getChatMessages(editor.floor)[0];
      if (current?.message !== editor.original) throw new Error('原回复已变化，请关闭编辑器并重新打开。');
      await waitGlobalInitialized('Mvu');
      const option = { type: 'message' as const, message_id: editor.floor };
      const baseline = _.cloneDeep(Mvu.getMvuData(option));
      const next = await Mvu.parseMessage(editor.value, _.cloneDeep(baseline));
      if (captured !== version.current) throw new Error('聊天已切换，已取消写入。');
      if (!next?.stat_data) throw new Error('MVU 没有返回有效更新结果，请检查代码。');
      if (checkMvuPatchResult(editor.value, next.stat_data))
        throw new Error(checkMvuPatchResult(editor.value, next.stat_data));
      if (!_.isEqual(Mvu.getMvuData(option), baseline)) throw new Error('变量已被其他更新修改，请重新打开后再保存。');
      await Mvu.replaceMvuData(next, option);
      const stored = Mvu.getMvuData(option);
      if (!_.isEqual(stored.stat_data, next.stat_data))
        throw new Error('写入结果与修正内容不一致，请检查变量校验提示。');
      const notices = describeMvuChanges(diffMvu(baseline.stat_data, stored.stat_data));
      saveBatch({ id: Date.now(), floor: editor.floor, at: Date.now(), notices, code: editor.value });
      setBatches(previous =>
        [
          {
            id: Date.now(),
            floor: editor.floor,
            at: Date.now(),
            notices,
            code: editor.value,
            error: notices.length ? undefined : '手动处理已完成，变量没有变化。',
          },
          ...previous.filter(batch => batch.floor !== editor.floor),
        ].slice(0, 12),
      );
      setEditor(null);
      setUpdating(false);
    } catch (reason) {
      setFeedback(reason instanceof Error ? reason.message : String(reason));
    } finally {
      processing.current = false;
      setSaving(false);
    }
  };
  const latest = batches[0];
  return (
    <>
      <details className={`campus-mvu-notice${updating ? ' is-updating' : ''}`}>
        <summary>
          <span className="campus-mvu-orbit">
            <FileText size={16} />
          </span>
          <span>
            MVU 更新{' '}
            <small role="status">
              {updating
                ? '更新中'
                : latest?.error
                  ? '需要检查'
                  : latest?.historical
                    ? '历史回读'
                    : latest
                      ? '更新完毕'
                      : '等待更新'}
            </small>
          </span>
          {latest?.error && <b>!</b>}
          <ChevronDown size={14} />
        </summary>
        <div className="campus-mvu-list">
          {!batches.length && <p>{updating ? '正在整理校园变化…' : '暂无更新记录，等待下一次 MVU 更新。'}</p>}
          {batches.map(batch => (
            <section key={batch.id}>
              <header>
                第 {batch.floor + 1} 楼 ·{' '}
                <time>
                  {batch.historical
                    ? '历史快照对比'
                    : new Date(batch.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </time>
              </header>
              {batch.error && (
                <div className="campus-mvu-error" role="alert">
                  <strong>需要检查更新</strong>
                  <p>{batch.error}</p>
                  <p>可在酒馆对该回复重新生成（重 roll），或手动修正下方更新代码。</p>
                </div>
              )}
              {!batch.error && !batch.notices.length && (
                <p>可用快照未显示差异；可能是重复赋值。请结合更新代码核对当前变量。</p>
              )}
              {batch.notices.map((notice, index) => {
                const Icon = icons[notice.category as keyof typeof icons] || FileText;
                return (
                  <details className="campus-mvu-event" key={index}>
                    <summary>
                      <Icon size={18} />
                      <span>
                        <strong>{notice.title}</strong>
                        <small>{notice.changes.length} 项变化 · 点击查看</small>
                      </span>
                    </summary>
                    <dl>
                      {notice.changes.map((change, i) => (
                        <div key={i}>
                          <dt>{change.path.join(' › ')}</dt>
                          <dd>
                            <del>{displayMvuValue(change.before)}</del>
                            <span>→ {displayMvuValue(change.after)}</span>
                          </dd>
                        </div>
                      ))}
                    </dl>
                  </details>
                );
              })}
              <button type="button" onClick={() => openEditor(batch)}>
                手动修正更新代码
              </button>
              {batch.code && (
                <details>
                  <summary>查看更新代码</summary>
                  <pre>{batch.code}</pre>
                </details>
              )}
            </section>
          ))}
          {!editor && feedback && <p role="alert">{feedback}</p>}
        </div>
      </details>
      {editor && (
        <div className="campus-tablet-modal campus-tablet-editor">
          <div role="dialog" aria-modal="true" aria-label="手动修正 MVU 更新">
            <header>
              <strong>手动修正 · 第 {editor.floor + 1} 楼</strong>
              <button disabled={saving} onClick={() => setEditor(null)} aria-label="关闭">
                <X size={18} />
              </button>
            </header>
            <div>
              <p>仅应用这里的修正指令到此楼层当前变量，不会重放整条回复。请勿再次执行已经生效的累加或追加指令。</p>
              <textarea
                autoFocus
                aria-label="MVU 更新代码"
                value={editor.value}
                disabled={saving}
                onChange={event => setEditor({ ...editor, value: event.target.value })}
              />
              <p role="alert">{feedback}</p>
              <div className="campus-tablet-operation-actions">
                <button disabled={saving} onClick={() => setEditor(null)}>
                  取消
                </button>
                <button disabled={saving} onClick={() => void apply()}>
                  {saving ? '应用中…' : '应用修正'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
