import { BookOpen, Building2, Check, GraduationCap, Sparkles, UserCircle2, UserRound, Users } from 'lucide-react';
import { useEffect, useState } from 'react';
import { CenterModal } from '../ui/Modal';

export interface ExportItem {
  id: string;
  label: string;
  extra?: string;
}

export interface ExportSection {
  id: string;
  title: string;
  items: ExportItem[];
  selected: string[];
  setSelected: (next: string[]) => void;
}

function toggleId(list: string[], id: string) {
  return list.includes(id) ? list.filter(item => item !== id) : [...list, id];
}

const TAB_ICONS = {
  校规: BookOpen,
  角色: Users,
  活动: Sparkles,
  建筑: Building2,
  校园类型: GraduationCap,
  相貌: UserRound,
  性格: Users,
  身份: UserCircle2,
};

export function WorkshopExportModal({
  open,
  fileName,
  sections,
  onFileNameChange,
  onClose,
  onExport,
}: {
  open: boolean;
  fileName: string;
  sections: ExportSection[];
  onFileNameChange: (value: string) => void;
  onClose: () => void;
  onExport: () => void;
}) {
  const [tab, setTab] = useState(sections[0]?.id || '');
  useEffect(() => {
    if (!sections.some(item => item.id === tab)) {
      setTab(sections[0]?.id || '');
    }
  }, [sections, tab]);
  const current = sections.find(item => item.id === tab) || sections[0];

  return (
    <CenterModal isOpen={open} onClose={onClose} className="w-[calc(100%-2rem)] max-w-[320px] max-h-[80vh] p-0">
      <div className="p-4 border-b border-border-default">
        <h3 className="font-bold text-text-primary">导出工坊文件</h3>
        <input
          value={fileName}
          onChange={event => onFileNameChange(event.target.value)}
          placeholder="文件名"
          className="mt-3 w-full rounded-xl px-3 py-2 text-sm theme-field"
        />
      </div>
      <div className={`grid gap-1 p-2 bg-surface ${sections.length === 4 ? 'grid-cols-4' : sections.length === 3 ? 'grid-cols-3' : sections.length === 2 ? 'grid-cols-2' : 'grid-cols-1'}`}>
        {sections.map(section => {
          const Icon = TAB_ICONS[section.title as keyof typeof TAB_ICONS] || BookOpen;
          return (
            <button
              key={section.id}
              type="button"
              onClick={() => setTab(section.id)}
              className={`py-2 rounded-xl text-[11px] font-bold flex flex-col items-center gap-0.5 ${
                current?.id === section.id ? 'bg-surface-solid text-[color:var(--action-text)] shadow-sm' : 'text-text-secondary hover-fill'
              }`}
            >
              <Icon className="w-3.5 h-3.5" />
              {section.title}
            </button>
          );
        })}
      </div>
      {current && (
        <div className="p-4 overflow-y-auto hide-scrollbar max-h-[42vh]">
          <div className="flex items-center justify-between mb-2">
            <div className="text-xs font-bold text-text-secondary">{current.title}</div>
            <button
              type="button"
              className="text-[10px] text-[color:var(--action-text)] font-bold"
              onClick={() =>
                current.setSelected(current.selected.length === current.items.length ? [] : current.items.map(item => item.id))
              }
            >
              {current.selected.length === current.items.length ? '取消全选' : '全选'}
            </button>
          </div>
          <div className="space-y-1.5">
            {current.items.map(item => (
              <label key={item.id} className="flex items-start gap-2 rounded-xl bg-surface px-2.5 py-2">
                <input
                  type="checkbox"
                  checked={current.selected.includes(item.id)}
                  onChange={() => current.setSelected(toggleId(current.selected, item.id))}
                  className="mt-0.5 accent-[var(--selected-mark)]"
                />
                <span className="min-w-0">
                  <span className="block text-xs font-bold text-text-primary truncate">{item.label}</span>
                  {item.extra ? <span className="block text-[10px] text-text-secondary">{item.extra}</span> : null}
                </span>
              </label>
            ))}
            {!current.items.length && <p className="text-[11px] text-text-secondary px-1">暂无可选项</p>}
          </div>
        </div>
      )}
      <div className="p-4 flex gap-2 border-t border-border-default">
        <button type="button" onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-border-default text-sm font-bold text-text-secondary">
          取消
        </button>
        <button type="button" onClick={onExport} className="flex-1 py-2.5 rounded-xl accent-btn text-sm font-bold flex items-center justify-center gap-1">
          <Check className="w-4 h-4" />
          导出
        </button>
      </div>
    </CenterModal>
  );
}
