const STORAGE_KEY = 'campus-app-avatars';
const OUTPUT_SIZE = 256;
const OUTPUT_QUALITY = 0.72;

export interface AvatarStore {
  player: string | null;
  characters: Record<string, string>;
}

function getStorage(): Storage | null {
  try {
    const parent = window.parent && window.parent !== window ? window.parent : window;
    return parent.localStorage;
  } catch {
    try {
      return window.localStorage;
    } catch {
      return null;
    }
  }
}

function getScope(): string {
  const globalAny = window as any;
  const parentAny = (() => {
    try {
      return window.parent as any;
    } catch {
      return null;
    }
  })();
  const candidates = [
    () => (typeof getCurrentChatId === 'function' ? getCurrentChatId() : ''),
    () => globalAny.getChatId?.(),
    () => parentAny?.chat_metadata?.chat_id,
    () => parentAny?.name2,
  ];
  for (const read of candidates) {
    try {
      const value = String(read() || '').trim();
      if (value) return value;
    } catch {
      // ignore
    }
  }
  return 'default';
}

function emptyStore(): AvatarStore {
  return { player: null, characters: {} };
}

function readAll(): Record<string, AvatarStore> {
  const storage = getStorage();
  if (!storage) return {};
  try {
    const parsed = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function writeAll(all: Record<string, AvatarStore>) {
  const storage = getStorage();
  if (!storage) return;
  storage.setItem(STORAGE_KEY, JSON.stringify(all));
}

export function loadAvatarStore(): AvatarStore {
  const all = readAll();
  const scoped = all[getScope()];
  if (scoped && typeof scoped === 'object') {
    return {
      player: typeof scoped.player === 'string' ? scoped.player : null,
      characters: scoped.characters && typeof scoped.characters === 'object' ? scoped.characters : {},
    };
  }
  return emptyStore();
}

function saveAvatarStore(store: AvatarStore) {
  const all = readAll();
  all[getScope()] = store;
  try {
    writeAll(all);
  } catch (error) {
    console.warn('[校园APP] 头像保存失败，可能超出本地存储限制:', error);
    throw error;
  }
}

export function compressAvatar(dataUrl: string): Promise<string> {
  return new Promise(resolve => {
    if (!dataUrl) {
      resolve(dataUrl);
      return;
    }
    const image = new Image();
    image.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = OUTPUT_SIZE;
      canvas.height = OUTPUT_SIZE;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve(dataUrl);
        return;
      }
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, OUTPUT_SIZE, OUTPUT_SIZE);
      ctx.drawImage(image, 0, 0, OUTPUT_SIZE, OUTPUT_SIZE);
      resolve(canvas.toDataURL('image/jpeg', OUTPUT_QUALITY));
    };
    image.onerror = () => resolve(dataUrl);
    image.src = dataUrl;
  });
}

export async function persistPlayerAvatar(dataUrl: string | null): Promise<string | null> {
  const store = loadAvatarStore();
  store.player = dataUrl ? await compressAvatar(dataUrl) : null;
  saveAvatarStore(store);
  return store.player;
}

export async function persistCharacterAvatar(id: string, dataUrl: string | null): Promise<string | null> {
  const store = loadAvatarStore();
  if (dataUrl) {
    store.characters[id] = await compressAvatar(dataUrl);
  } else {
    delete store.characters[id];
  }
  saveAvatarStore(store);
  return store.characters[id] || null;
}
