import { motion } from 'framer-motion';
import {
    BookOpen,
    BookUser,
    Cloud,
    CloudRain,
    CloudSnow,
    GraduationCap,
    Hammer,
    Image,
    Map,
    MessageSquare,
    Settings,
    Sparkles,
    Sun,
    User,
} from 'lucide-react';
import React from 'react';
import { UpdateBanner } from '../shared/UpdateBanner';
import {
    formatMvuDate,
    formatMvuTime,
    formatMvuWeather,
    MvuTime,
    MvuWeather,
    useMvuVariable,
} from '../../hooks/useMvuData';
import { CampusBuilding, Character, Player, SchoolRule } from '../../types';

interface HomeScreenProps {
  player: Player;
  characters: Character[];
  rules: SchoolRule[];
  buildings: CampusBuilding[];
  onOpenApp: (tab: 'profile' | 'contacts' | 'rules' | 'map' | 'forum' | 'gallery' | 'settings' | 'appSettings') => void;
  hasUpdate?: boolean;
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ player, onOpenApp, hasUpdate = false }) => {
  const [mvuTime] = useMvuVariable<MvuTime>('时间', { 年: 2024, 月: 9, 日: 1, 小时: 12, 分钟: 30, 星期: 1 });
  const [mvuWeather] = useMvuVariable<MvuWeather>('天气', { 温度: 26, 天气描述: '晴' });

  const getWeatherIcon = () => {
    const desc = String((mvuWeather as any)?.天气描述 ?? '');
    if (desc.includes('雨')) return CloudRain;
    if (desc.includes('雪')) return CloudSnow;
    if (desc.includes('云') || desc.includes('阴')) return Cloud;
    return Sun;
  };

  const WeatherIcon = getWeatherIcon();

  const appIcons = [
    {
      id: 'profile' as const,
      label: '个人信息',
      icon: User,
      gradient: 'from-pink-400 to-rose-500',
      sub: player.name || '玩家',
    },
    {
      id: 'contacts' as const,
      label: '同学录',
      icon: BookUser,
      gradient: 'from-purple-400 to-indigo-500',
      sub: '联系人',
    },
    {
      id: 'rules' as const,
      label: '校规手册',
      icon: BookOpen,
      gradient: 'from-amber-400 to-orange-500',
      sub: '规章制度',
    },
    {
      id: 'map' as const,
      label: '校园地图',
      icon: Map,
      gradient: 'from-emerald-400 to-teal-500',
      sub: '探索设施',
    },
    {
      id: 'forum' as const,
      label: '校园论坛',
      icon: MessageSquare,
      gradient: 'from-sky-400 to-blue-500',
      sub: '八卦交流',
    },
    {
      id: 'gallery' as const,
      label: '角色图库',
      icon: Image,
      gradient: 'from-cyan-400 to-teal-500',
      sub: '立绘与头像',
    },
    {
      id: 'settings' as const,
      label: '工坊',
      icon: Hammer,
      gradient: 'from-slate-400 to-zinc-600',
      sub: '导入导出',
    },
    {
      id: 'appSettings' as const,
      label: '设置',
      icon: Settings,
      gradient: 'from-gray-400 to-slate-600',
      sub: '版本更新',
      badge: hasUpdate,
    },
  ];

  return (
    <div className="w-full h-full flex flex-col justify-between px-5 pt-8 pb-24 select-none overflow-y-auto hide-scrollbar">
      {/* Top Clock & Weather Widget */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4 }}
        className="flex flex-col items-center justify-center my-2 text-center"
      >
        <div className="text-5xl font-extralight tracking-tight text-text-primary font-sans">{formatMvuTime(mvuTime)}</div>
        <div className="text-xs font-medium text-text-secondary mt-1 flex items-center gap-1.5">
          <span>{formatMvuDate(mvuTime)}</span>
          <span className="inline-block w-1 h-1 rounded-full bg-border-default"></span>
          <span className="flex items-center gap-1 text-amber-500">
            <WeatherIcon className="w-3.5 h-3.5" />
            {formatMvuWeather(mvuWeather)}
          </span>
        </div>
      </motion.div>

      {/* Campus Card / Status Widget */}
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4, delay: 0.1 }}
        onClick={() => onOpenApp('profile')}
        className="bg-surface backdrop-blur-md rounded-2xl p-3.5 border border-border-default shadow-sm cursor-pointer hover:bg-surface-solid transition-all flex items-center justify-between gap-3 my-3"
      >
        <div className="flex items-center gap-3 min-w-0">
          <div className="w-11 h-11 rounded-full bg-gradient-to-tr from-pink-400 to-rose-400 flex items-center justify-center text-white shadow-sm shrink-0 overflow-hidden">
            {player.avatar ? (
              <img src={player.avatar} alt={player.name} className="w-full h-full object-cover" />
            ) : (
              <GraduationCap className="w-6 h-6" />
            )}
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-1.5">
              <span className="font-bold text-sm text-text-primary truncate">
                {player.name || '同学'}
              </span>
              <span className="text-[10px] soft-chip px-1.5 py-0.5 rounded-full font-medium shrink-0">
                {player.identity || '南城大学'}
              </span>
            </div>
            <p className="text-[11px] text-text-secondary truncate mt-0.5 flex items-center gap-1">
              <Sparkles className="w-3 h-3 text-amber-500 shrink-0" />
              <span>今日校园生活已开启</span>
            </p>
          </div>
        </div>
      </motion.div>

      {/* Apps Grid */}
      <motion.div
        initial={{ opacity: 0, y: 15 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.2 }}
        className="grid grid-cols-3 gap-y-5 gap-x-4 my-auto py-2"
      >
        {appIcons.map(app => {
          const Icon = app.icon;
          return (
            <motion.button
              key={app.id}
              whileTap={{ scale: 0.92 }}
              onClick={() => onOpenApp(app.id)}
              className="flex flex-col items-center group cursor-pointer focus:outline-none"
            >
              <div className="relative">
                <div
                  className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${app.gradient} flex items-center justify-center text-white shadow-md group-hover:shadow-lg transition-all duration-200`}
                >
                  <Icon className="w-7 h-7 stroke-[1.75]" />
                </div>
                {'badge' in app && app.badge ? (
                  <span className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-rose-500 ring-2 ring-white" />
                ) : null}
              </div>
              <span className="text-xs font-medium text-text-primary mt-2 tracking-tight transition-colors">
                {app.label}
              </span>
            </motion.button>
          );
        })}
      </motion.div>

      {/* Subtle indicator bar */}
      <div className="w-12 h-1 bg-border-default rounded-full mx-auto mt-2 pointer-events-none" />
      <UpdateBanner />
    </div>
  );
};
