import { useCallback, useEffect, useMemo, useState } from 'react';
import { Character, ChatGroup, ChatMessageItem, ChatThread } from '../types';
import { getCharacterChatAliases, getChatDisplayName, getThreadMessages } from '../utils/chatParser';
import { useChatThreads } from './useChatThreads';

const STORAGE_KEY = 'campus-app-chat-read-state-v1';

type ReadMap = Record<string, string>;

function readMap(): ReadMap {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? (parsed as ReadMap) : {};
  } catch {
    return {};
  }
}

export function markChatMessagesRead(
  type: 'dm' | 'group',
  target: string,
  messages: ChatMessageItem[],
  aliases: string[] = [],
) {
  const next = readMap();
  for (const name of [target, ...aliases]) next[chatThreadKey(type, name)] = chatFingerprint(messages);
  writeMap(next);
}

function writeMap(next: ReadMap) {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
    window.dispatchEvent(new Event('campus-chat-read'));
  } catch {
    // ignore quota / private mode
  }
}

export function chatThreadKey(type: 'dm' | 'group', target: string): string {
  return `${type}:${String(target || '').trim()}`;
}

export function chatFingerprint(messages: ChatMessageItem[]): string {
  const last = messages[messages.length - 1];
  if (!last) return '';
  return `${last.id}::${last.timestamp}::${last.content}`;
}

function hasUnreadMessages(messages: ChatMessageItem[], lastRead: string | undefined): boolean {
  const fingerprint = chatFingerprint(messages);
  if (!fingerprint) return false;
  return fingerprint !== String(lastRead || '');
}

export function useChatUnread(characters: Character[], groups: ChatGroup[]) {
  const threads = useChatThreads();
  const [readState, setReadState] = useState<ReadMap>(() => readMap());

  useEffect(() => {
    writeMap(readState);
  }, [readState]);

  const markThreadRead = useCallback(
    (type: 'dm' | 'group', target: string, aliases: string[] = []) => {
      const messages = getThreadMessages(threads, type, target, aliases);
      const fingerprint = chatFingerprint(messages);
      const names = [target, ...aliases].map(item => String(item || '').trim()).filter(Boolean);
      setReadState(prev => {
        const next = { ...prev };
        for (const name of names) {
          const key = chatThreadKey(type, name);
          if (fingerprint) next[key] = fingerprint;
          else delete next[key];
        }
        // Also mark exact matched thread targets found in data
        for (const thread of threads) {
          if (thread.type !== type) continue;
          if (!names.includes(thread.target)) continue;
          const fp = chatFingerprint(thread.messages);
          if (fp) next[chatThreadKey(type, thread.target)] = fp;
        }
        return next;
      });
    },
    [threads],
  );

  const isDmUnread = useCallback(
    (character: Character) => {
      const aliases = getCharacterChatAliases(character);
      const target = getChatDisplayName(character);
      const messages = getThreadMessages(threads, 'dm', target, aliases);
      const keys = [target, ...aliases].map(name => chatThreadKey('dm', name));
      const lastRead = keys.map(key => readState[key]).find(Boolean);
      return hasUnreadMessages(messages, lastRead);
    },
    [readState, threads],
  );

  const isGroupUnread = useCallback(
    (group: ChatGroup) => {
      const messages = getThreadMessages(threads, 'group', group.name);
      return hasUnreadMessages(messages, readState[chatThreadKey('group', group.name)]);
    },
    [readState, threads],
  );

  const matesUnread = useMemo(
    () => characters.some(character => !character.isHidden && isDmUnread(character)),
    [characters, isDmUnread],
  );

  const groupsUnread = useMemo(() => groups.some(group => isGroupUnread(group)), [groups, isGroupUnread]);

  const hasAnyUnread = matesUnread || groupsUnread;

  return {
    threads,
    hasAnyUnread,
    matesUnread,
    groupsUnread,
    isDmUnread,
    isGroupUnread,
    markThreadRead,
  };
}

/** 仅用于主页红点：不依赖具体角色列表，只要会话未读就提示 */
export function useChatUnreadBadge() {
  const threads = useChatThreads();
  const [readState, setReadState] = useState<ReadMap>(() => readMap());

  useEffect(() => {
    const sync = () => setReadState(readMap());
    sync();
    window.addEventListener('storage', sync);
    window.addEventListener('campus-chat-read', sync);
    const timer = window.setInterval(sync, 800);
    return () => {
      window.removeEventListener('storage', sync);
      window.removeEventListener('campus-chat-read', sync);
      window.clearInterval(timer);
    };
  }, []);

  const hasAnyUnread = useMemo(
    () =>
      threads.some(thread => hasUnreadMessages(thread.messages, readState[chatThreadKey(thread.type, thread.target)])),
    [readState, threads],
  );

  const matesUnread = useMemo(
    () =>
      threads.some(
        thread =>
          thread.type === 'dm' && hasUnreadMessages(thread.messages, readState[chatThreadKey('dm', thread.target)]),
      ),
    [readState, threads],
  );

  const groupsUnread = useMemo(
    () =>
      threads.some(
        thread =>
          thread.type === 'group' &&
          hasUnreadMessages(thread.messages, readState[chatThreadKey('group', thread.target)]),
      ),
    [readState, threads],
  );

  const unreadDmThreads = useMemo(
    () =>
      threads.filter(
        thread =>
          thread.type === 'dm' && hasUnreadMessages(thread.messages, readState[chatThreadKey('dm', thread.target)]),
      ),
    [threads, readState],
  );
  return { hasAnyUnread, matesUnread, groupsUnread, threads, unreadDmThreads, readState };
}

export type { ChatThread };
