import {
  ArrowDown,
  ArrowLeftRight,
  ChevronDown,
  FileText,
  MessageSquare,
  MapPin,
  MoreHorizontal,
  Send,
  Settings,
  Sun,
  User,
  X,
} from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useCampusTheme } from '../hooks/useCampusTheme';
import { formatMvuTime, useMvuSnapshot } from '../hooks/useMvuData';
import {
  clickTavernSend,
  clickTavernStop,
  isTavernGenerating,
  getTavernInput,
  setTavernInput,
} from '../utils/fillTavernInput';
import {
  CampusDocument,
  compileTabletHideRules,
  renderTabletMessage,
  replaceTabletBody,
  splitTabletContent,
} from '../utils/tabletContent';
import { loadAvatarStore } from '../utils/avatarStore';
import { getPresetCharacterImages, presetCharacterImages } from '../utils/presetCharacterImages';
import { useForumGeneration } from '../hooks/useForumGeneration';
import { chatFingerprint, chatThreadKey, useChatUnreadBadge } from '../hooks/useChatUnread';
import { MvuUpdateNotice } from './MvuUpdateNotice';
import './CampusTablet.css';

function DocumentCard({ item }: { item: CampusDocument }) {
  return (
    <details className="campus-document">
      <summary>
        <FileText size={17} />
        <span>
          <small>
            {item.office} · {item.title}
          </small>
          <strong>{item.subject}</strong>
        </span>
        <ChevronDown size={15} />
      </summary>
      <div className="campus-document-detail">
        <div className="campus-document-heading">
          {item.office}
          <h3>{item.title}</h3>
        </div>
        <dl>
          <dt>事项名称</dt>
          <dd>{item.subject}</dd>
          {item.fields.map(([key, value], index) => (
            <div key={index}>
              <dt>{key}</dt>
              <dd>{value}</dd>
            </div>
          ))}
        </dl>
        <details className="campus-document-original">
          <summary>查看完整内容</summary>
          <p>{item.raw}</p>
        </details>
      </div>
    </details>
  );
}

function MessageBody({
  message,
  streaming = false,
  avatars,
  hideRules,
}: {
  message: ChatMessage;
  streaming?: boolean;
  avatars: Record<string, string>;
  hideRules: string;
}) {
  const blocks = useMemo(() => {
    const parts =
      message.role === 'user' ? splitTabletContent(message.message) : [{ type: 'text' as const, raw: message.message }];
    return parts.map(part =>
      part.type === 'document'
        ? part
        : { ...part, html: renderTabletMessage(part.raw, message.message_id, streaming, avatars, hideRules) },
    );
  }, [message, streaming, avatars, hideRules]);
  return (
    <>
      {blocks.map((part, index) =>
        part.type === 'document' ? (
          <DocumentCard key={index} item={part.document} />
        ) : part.raw.trim() ? (
          <div key={index} className="campus-tablet-prose" dangerouslySetInnerHTML={{ __html: part.html }} />
        ) : null,
      )}
    </>
  );
}

export function CampusTablet({ onFlip }: { onFlip: () => void }) {
  const data = useMvuSnapshot();
  const { isDark } = useCampusTheme();
  const { unreadDmThreads, readState } = useChatUnreadBadge();
  const { state: forumState } = useForumGeneration();
  const forumUnread = forumState.unreadPostIds?.length || 0;
  const seenForumGeneration = useRef(forumState.lastGeneratedAt);
  const [bubble, setBubble] = useState<{
    target: string;
    fingerprint: string;
    content: string;
    forum?: boolean;
  } | null>(null);
  const [bubblePhase, setBubblePhase] = useState<'visible' | 'leaving' | 'hidden'>('hidden');
  const seenMessages = useRef(new Map<string, string>());
  useEffect(() => {
    let latest: typeof bubble = null;
    for (const thread of unreadDmThreads) {
      const fingerprint = chatFingerprint(thread.messages);
      if (seenMessages.current.get(thread.target) !== fingerprint) {
        seenMessages.current.set(thread.target, fingerprint);
        const last = thread.messages[thread.messages.length - 1];
        if (last && last.senderName !== data.玩家?.姓名 && last.senderName !== '{{user}}') {
          latest = { target: thread.target, fingerprint, content: last.kind === 'image' ? '[图片]' : last.content };
        }
      }
    }
    if (latest) {
      setBubble(latest);
      setBubblePhase('visible');
    }
  }, [unreadDmThreads, data.玩家?.姓名]);
  useEffect(() => {
    const generatedAt = forumState.lastGeneratedAt;
    if (generatedAt === seenForumGeneration.current) return;
    seenForumGeneration.current = generatedAt;
    if (!generatedAt || !forumUnread) return;
    setBubble({ target: '校园论坛', fingerprint: `forum:${generatedAt}`, content: '论坛有新内容', forum: true });
    setBubblePhase('visible');
  }, [forumState.lastGeneratedAt, forumUnread]);
  useEffect(() => {
    if (!bubble) return;
    const leave = window.setTimeout(() => setBubblePhase('leaving'), 3360);
    const hide = window.setTimeout(() => setBubblePhase('hidden'), 3720);
    return () => {
      window.clearTimeout(leave);
      window.clearTimeout(hide);
    };
  }, [bubble]);
  useEffect(() => {
    const subscription = eventOn(tavern_events.CHAT_CHANGED, () => {
      seenMessages.current.clear();
      seenForumGeneration.current = 0;
      setBubble(null);
      setBubblePhase('hidden');
    });
    return () => subscription.stop();
  }, []);
  const unreadCount = (thread: (typeof unreadDmThreads)[number]) => {
    const lastRead = readState[chatThreadKey('dm', thread.target)];
    const index = thread.messages.findIndex(message => chatFingerprint([message]) === lastRead);
    return thread.messages
      .slice(index + 1)
      .filter(message => message.senderName !== data.玩家?.姓名 && message.senderName !== '{{user}}').length;
  };
  const openDm = (target: string) => window.dispatchEvent(new CustomEvent('campus-open-dm', { detail: target }));
  const openForum = () => window.dispatchEvent(new Event('campus-open-forum'));
  const [scrollTarget, setScrollTarget] = useState<number | null>(null);
  const [editing, setEditing] = useState<{ index: number; original: string; value: string } | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState(() => getTavernInput()?.value || '');
  const [available, setAvailable] = useState(false);
  const [busy, setBusy] = useState(isTavernGenerating);
  const [streamFloor, setStreamFloor] = useState<number | null>(null);
  const generationBaseline = useRef(-1);
  const [error, setError] = useState('');
  const [limit, setLimit] = useState(40);
  const [detail, setDetail] = useState<CampusDocument[] | null>(null);
  const [following, setFollowing] = useState(true);
  const [readingSettings, setReadingSettings] = useState(false);
  const [fontSize, setFontSize] = useState(() => {
    try {
      const saved = Number(localStorage.getItem('campus-tablet-font-size'));
      return Number.isInteger(saved) && saved >= 14 && saved <= 22 ? saved : 14;
    } catch {
      return 14;
    }
  });
  useEffect(() => {
    try {
      localStorage.setItem('campus-tablet-font-size', String(fontSize));
    } catch (reason) {
      console.warn('[校园平板] 字号保存失败', reason);
    }
  }, [fontSize]);
  const [avatarStore, setAvatarStore] = useState(loadAvatarStore);
  const [hideRules, setHideRules] = useState(() => {
    try {
      return localStorage.getItem('campus-tablet-hide-rules') || '';
    } catch {
      return '';
    }
  });
  const [ruleDraft, setRuleDraft] = useState(hideRules);
  const [ruleFeedback, setRuleFeedback] = useState('');
  const avatars = useMemo(() => {
    const result: Record<string, string> = {};
    Object.entries(presetCharacterImages).forEach(([name, images]) => {
      result[name] = images.avatar;
    });
    Object.entries(data.角色 || {}).forEach(([id, character]) => {
      const image = avatarStore.characters[id] || getPresetCharacterImages(character.姓名, id)?.avatar;
      if (image) {
        result[id] = image;
        result[character.姓名] = image;
      }
    });
    Object.assign(result, avatarStore.characters);
    if (avatarStore.player && data.玩家?.姓名) result[data.玩家.姓名] = avatarStore.player;
    return result;
  }, [data.角色, data.玩家?.姓名, avatarStore]);
  useEffect(() => {
    const refresh = () =>
      setAvatarStore(previous => {
        const next = loadAvatarStore();
        return _.isEqual(previous, next) ? previous : next;
      });
    const timer = window.setInterval(refresh, 800);
    window.addEventListener('storage', refresh);
    const subscription = eventOn(tavern_events.CHAT_CHANGED, refresh);
    return () => {
      window.clearInterval(timer);
      window.removeEventListener('storage', refresh);
      subscription.stop();
    };
  }, []);
  const scrollRef = useRef<HTMLDivElement>(null);
  const followingRef = useRef(true);
  const sendingRef = useRef(false);
  const limitRef = useRef(limit);
  const attemptRef = useRef<{ value: string; last: number } | null>(null);
  const timeoutRef = useRef<number | null>(null);
  limitRef.current = limit;
  const parts = useMemo(() => splitTabletContent(draft), [draft]);
  const documents = parts.flatMap(part => (part.type === 'document' ? [part.document] : []));
  const body = parts
    .filter(part => part.type === 'text')
    .map(part => part.raw)
    .join('');
  const groups = new Map<string, CampusDocument[]>();
  documents.forEach(item => groups.set(item.label, [...(groups.get(item.label) || []), item]));

  useEffect(() => {
    let disposed = false;
    let timer: number | null = null;
    const readMessages = () => {
      if (disposed) return;
      try {
        const last = getLastMessageId();
        const next =
          last < 0
            ? []
            : getChatMessages(`${Math.max(0, last - limitRef.current + 1)}-${last}`).filter(
                message => message.role !== 'system',
              );
        setMessages(previous => (_.isEqual(previous, next) ? previous : _.cloneDeep(next)));
      } catch (reason) {
        console.warn('[校园平板] 无法读取聊天记录', reason);
      }
    };
    const sync = () => {
      const input = getTavernInput();
      setAvailable(Boolean(input));
      if (isTavernGenerating()) setBusy(true);
      const attempt = attemptRef.current;
      if (input && (!attempt || input.value)) setDraft(current => (current === input.value ? current : input.value));
      if (attempt) {
        const last = getLastMessageId();
        const sent =
          last > attempt.last &&
          getChatMessages(`${Math.max(0, attempt.last + 1)}-${last}`).some(message => message.role === 'user');
        if (sent) {
          attemptRef.current = null;
          sendingRef.current = false;
          if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
        }
      }
    };
    const schedule = () => {
      if (timer !== null) return;
      timer = window.setTimeout(() => {
        timer = null;
        readMessages();
        try {
          sync();
        } catch (reason) {
          console.warn('[校园平板] 草稿同步失败', reason);
        }
      }, 120);
    };
    const reset = () => {
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
      attemptRef.current = null;
      sendingRef.current = false;
      setBusy(false);
      setStreamFloor(null);
      setScrollTarget(null);
      setError('');
      setDetail(null);
      setEditing(null);
      setMessages([]);
      setLimit(40);
      limitRef.current = 40;
      followingRef.current = true;
      setFollowing(true);
      schedule();
    };
    const subscriptions: EventOnReturn[] = [];
    [
      tavern_events.MESSAGE_SENT,
      tavern_events.MESSAGE_RECEIVED,
      tavern_events.MESSAGE_UPDATED,
      tavern_events.MESSAGE_EDITED,
      tavern_events.MESSAGE_DELETED,
      tavern_events.MESSAGE_SWIPED,
      tavern_events.USER_MESSAGE_RENDERED,
      tavern_events.CHARACTER_MESSAGE_RENDERED,
      tavern_events.SETTINGS_UPDATED,
    ].forEach(event => subscriptions.push(eventOn(event, schedule)));
    subscriptions.push(
      eventOn(tavern_events.STREAM_TOKEN_RECEIVED, () => {
        setBusy(true);
        const last = getLastMessageId();
        const message = getChatMessages(last)[0];
        if (message?.role === 'assistant' && last >= generationBaseline.current) {
          setStreamFloor(last);
        }
        schedule();
      }),
    );
    subscriptions.push(eventOn(tavern_events.CHAT_CHANGED, reset));
    subscriptions.push(
      eventOn(tavern_events.GENERATION_STARTED, (_type, _options, dryRun) => {
        if (dryRun) return;
        generationBaseline.current = getLastMessageId();
        setStreamFloor(null);
        setBusy(true);
      }),
    );
    const ended = () => {
      const last = getLastMessageId();
      const message = getChatMessages(last)[0];
      if (message?.role === 'assistant') {
        followingRef.current = false;
        setFollowing(false);
        setScrollTarget(last);
      }
      setStreamFloor(null);
      setBusy(false);
      readMessages();
      schedule();
    };
    subscriptions.push(
      eventOn(tavern_events.GENERATION_ENDED, ended),
      eventOn(tavern_events.GENERATION_STOPPED, ended),
    );
    let parent: Document;
    try {
      parent = window.parent.document;
    } catch {
      parent = document;
    }
    const onInput = () => {
      try {
        sync();
      } catch (reason) {
        console.warn('[校园平板] 草稿同步失败', reason);
      }
    };
    parent.addEventListener('input', onInput);
    readMessages();
    sync();
    const polling = window.setInterval(() => {
      try {
        sync();
      } catch (reason) {
        console.warn('[校园平板] 草稿同步失败', reason);
      }
    }, 350);
    return () => {
      disposed = true;
      parent.removeEventListener('input', onInput);
      subscriptions.forEach(subscription => subscription.stop());
      window.clearInterval(polling);
      if (timer !== null) window.clearTimeout(timer);
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current);
    };
  }, []);

  useEffect(() => {
    const last = getLastMessageId();
    if (last >= 0)
      setMessages(
        getChatMessages(`${Math.max(0, last - limit + 1)}-${last}`).filter(message => message.role !== 'system'),
      );
  }, [limit]);
  useEffect(() => {
    if (followingRef.current && scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  useEffect(() => {
    if (busy || scrollTarget === null) return;
    const frame = window.requestAnimationFrame(() => {
      const feed = scrollRef.current;
      const article = feed?.querySelector<HTMLElement>(`[data-message-id="${scrollTarget}"]`);
      if (!feed || !article) return;
      const scale = feed.getBoundingClientRect().height / feed.offsetHeight || 1;
      feed.scrollTo({
        top: feed.scrollTop + (article.getBoundingClientRect().top - feed.getBoundingClientRect().top) / scale - 16,
        behavior: 'smooth',
      });
      setScrollTarget(null);
    });
    return () => window.cancelAnimationFrame(frame);
  }, [messages, busy, scrollTarget]);

  const send = () => {
    if (sendingRef.current || busy) return;
    const input = getTavernInput();
    if (!input?.value.trim()) return;
    setError('');
    sendingRef.current = true;
    attemptRef.current = { value: input.value, last: getLastMessageId() };
    try {
      clickTavernSend();
      timeoutRef.current = window.setTimeout(() => {
        if (!attemptRef.current) return;
        const attempt = attemptRef.current;
        attemptRef.current = null;
        sendingRef.current = false;
        const current = getTavernInput();
        if (current && !current.value) setTavernInput(attempt.value);
        setError('尚未确认发送，请检查酒馆提示；草稿已保留。');
      }, 10000);
    } catch (reason) {
      attemptRef.current = null;
      sendingRef.current = false;
      setError(reason instanceof Error ? reason.message : '无法发送，草稿已保留。');
    }
  };
  const updateOperation = (index: number, original: string, value: string) => {
    if (busy || sendingRef.current) return;
    const current = getTavernInput()?.value;
    if (current === undefined) return;
    const currentParts = splitTabletContent(current);
    if (currentParts[index]?.type !== 'document' || currentParts[index].raw !== original) {
      setError('草稿已变化，请重新打开该操作后再修改。');
      return;
    }
    const next = currentParts.map((part, i) => (i === index ? value : part.raw)).join('');
    if (setTavernInput(next)) {
      setDraft(next);
      setEditing(null);
      setError('');
    }
  };
  const time = data.时间;
  return (
    <section className={`campus-tablet${isDark ? ' is-dark' : ''}`} aria-label="校园平板">
      <header className="campus-tablet-context">
        <div className="campus-tablet-profile" title={data.玩家?.当前具体地点 || '校园'}>
          <span className="campus-tablet-avatar">
            {avatarStore.player ? <img src={avatarStore.player} alt="玩家头像" /> : <User size={19} />}
          </span>
          <span className="campus-tablet-profile-copy">
            <strong>{data.玩家?.姓名 || '校园来访者'}</strong>
            <small>{data.玩家?.身份 || '身份未记录'}</small>
          </span>
        </div>
        <div className="campus-tablet-context-center">
          <time>{time ? formatMvuTime(time) : '--:--'}</time>
          <span className="campus-tablet-weather">
            <Sun size={15} />
            {data.天气?.温度 != null ? `${data.天气.温度}°C` : data.天气?.天气描述 || '晴'}
          </span>
          <span className="campus-tablet-location">
            <MapPin size={13} />
            {[data.玩家?.当前所在地, data.玩家?.当前具体地点].filter(Boolean).join(' · ') || '校园'}
          </span>
        </div>
        <div className="campus-tablet-toolbar">
          <button
            className="campus-tablet-settings"
            type="button"
            onClick={() => setReadingSettings(value => !value)}
            aria-expanded={readingSettings}
            title="阅读设置"
            aria-label="阅读设置"
          >
            <Settings size={18} />
          </button>
          <button type="button" onClick={onFlip} title="切换展开方向" aria-label="切换展开方向">
            <ArrowLeftRight size={18} />
          </button>
        </div>
      </header>
      <div className="campus-tablet-notifications" aria-label="校园消息通知">
        {bubble &&
          bubblePhase !== 'hidden' &&
          (bubble.forum ? forumUnread > 0 : unreadDmThreads.some(thread => thread.target === bubble.target)) && (
            <button
              key={`${bubble.target}:${bubble.fingerprint}`}
              type="button"
              className={`campus-dm-bubble ${bubblePhase === 'leaving' ? 'is-leaving' : ''}`}
              onClick={() => (bubble.forum ? openForum() : openDm(bubble.target))}
            >
              <span className="campus-dm-avatar">
                {bubble.forum ? (
                  <MessageSquare size={18} />
                ) : avatars[bubble.target] ? (
                  <img src={avatars[bubble.target]} alt="" />
                ) : (
                  <User size={19} />
                )}
              </span>
              <span className="campus-dm-copy">
                <strong>{bubble.forum ? '校园论坛' : bubble.target}</strong>
                <span>{bubble.content}</span>
              </span>
              <span className="campus-dm-count">
                {bubble.forum
                  ? Math.min(99, forumUnread)
                  : Math.min(99, unreadCount(unreadDmThreads.find(thread => thread.target === bubble.target)!)) || 1}
              </span>
            </button>
          )}
        <div className="campus-dm-reminders">
          {forumUnread > 0 && (bubblePhase === 'hidden' || !bubble?.forum) && (
            <button
              type="button"
              className="campus-dm-reminder campus-forum-reminder"
              onClick={openForum}
              title="打开校园论坛"
            >
              <span className="campus-dm-avatar">
                <MessageSquare size={13} />
              </span>
              <span>论坛有新内容</span>
              <span className="campus-dm-count">{Math.min(99, forumUnread)}</span>
            </button>
          )}
          {unreadDmThreads
            .filter(thread => unreadCount(thread) > 0 && (bubblePhase === 'hidden' || thread.target !== bubble?.target))
            .map(thread => (
              <button
                type="button"
                key={thread.target}
                className="campus-dm-reminder"
                onClick={() => openDm(thread.target)}
                title={`打开与${thread.target}的私聊`}
              >
                <span className="campus-dm-avatar">
                  {avatars[thread.target] ? <img src={avatars[thread.target]} alt="" /> : <User size={13} />}
                </span>
                <span>{thread.target}</span>
                <span className="campus-dm-count">{Math.min(99, unreadCount(thread))}</span>
              </button>
            ))}
        </div>
      </div>
      {readingSettings && (
        <div className="campus-tablet-reading-settings" role="group" aria-label="阅读字号">
          <span>正文字号</span>
          <button
            type="button"
            disabled={fontSize <= 14}
            onClick={() => setFontSize(value => value - 1)}
            aria-label="缩小字号"
          >
            A−
          </button>
          <span>{fontSize}</span>
          <button
            type="button"
            disabled={fontSize >= 22}
            onClick={() => setFontSize(value => value + 1)}
            aria-label="放大字号"
          >
            A＋
          </button>
          <div className="campus-tablet-hide-settings">
            <label htmlFor="campus-tablet-hide-rules">查找正则表达式</label>
            <p>每行一条，匹配内容将在生成结束后隐藏。支持 /表达式/flags；跨行匹配可使用 [\\s\\S]*?。</p>
            <textarea
              id="campus-tablet-hide-rules"
              rows={4}
              value={ruleDraft}
              onChange={event => {
                setRuleDraft(event.target.value);
                setRuleFeedback('');
              }}
              placeholder={'例如：/<think>[\\s\\S]*?<\\/think>/gi'}
            />
            <button
              type="button"
              onClick={() => {
                try {
                  compileTabletHideRules(ruleDraft);
                  localStorage.setItem('campus-tablet-hide-rules', ruleDraft);
                  setHideRules(ruleDraft);
                  setRuleFeedback('已保存，当前正文已刷新。');
                } catch (reason) {
                  setRuleFeedback(`无法保存：${reason instanceof Error ? reason.message : String(reason)}`);
                }
              }}
            >
              保存隐藏规则
            </button>
            <p role="status">{ruleFeedback}</p>
          </div>
        </div>
      )}
      <div
        className="campus-tablet-feed"
        style={{ fontSize }}
        ref={scrollRef}
        onScroll={() => {
          const el = scrollRef.current;
          if (!el) return;
          const follow = el.scrollHeight - el.scrollTop - el.clientHeight < 70;
          followingRef.current = follow;
          setFollowing(follow);
        }}
      >
        {messages[0]?.message_id > 0 && (
          <button
            type="button"
            className="campus-tablet-history"
            onClick={() => {
              followingRef.current = false;
              setLimit(value => value + 40);
            }}
          >
            查看更早的手记
          </button>
        )}
        {!messages.length && (
          <div className="campus-tablet-empty">
            <FileText size={32} />
            <h3>把今天写进校园手记</h3>
            <p>这里会同步显示酒馆中的对话。</p>
          </div>
        )}
        {messages.map(message => (
          <article
            key={message.message_id}
            data-message-id={message.message_id}
            className={`campus-tablet-message ${message.role === 'user' ? 'is-player' : ''}`}
          >
            {message.role === 'user' &&
              (avatarStore.player ? (
                <img
                  className="campus-tablet-player-mark campus-tablet-player-image"
                  src={avatarStore.player}
                  alt="玩家行动"
                />
              ) : (
                <User className="campus-tablet-player-mark" size={19} aria-label="玩家行动" />
              ))}
            <MessageBody
              message={message}
              streaming={busy && message.message_id === streamFloor}
              avatars={avatars}
              hideRules={hideRules}
            />
          </article>
        ))}
      </div>
      {!following && (
        <button
          type="button"
          className="campus-tablet-latest"
          onClick={() => {
            followingRef.current = true;
            setFollowing(true);
            if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
          }}
        >
          <ArrowDown size={13} />
          回到最新
        </button>
      )}
      <footer className="campus-tablet-composer">
        <MvuUpdateNotice />
        {busy && (
          <div className="campus-tablet-writing" role="status" aria-live="polite">
            故事正在续写<span>...</span>
          </div>
        )}
        {groups.size > 0 && (
          <div className="campus-tablet-chips">
            {Array.from(groups, ([label, items]) => (
              <button key={label} type="button" className="campus-tablet-chip" onClick={() => setDetail(items)}>
                <FileText size={13} />待{label} ×{items.length}
                <MoreHorizontal size={16} />
              </button>
            ))}
          </div>
        )}
        <div className="campus-tablet-composer-row">
          <div className="campus-tablet-inputrow">
            <textarea
              aria-label="校园平板输入栏"
              value={body}
              disabled={!available || busy}
              rows={2}
              placeholder={available ? '请输入你的选择或行动…' : '请先打开酒馆聊天'}
              onChange={event => {
                const current = getTavernInput()?.value;
                if (current === undefined) return;
                const next = replaceTabletBody(splitTabletContent(current), event.target.value);
                if (setTavernInput(next)) setDraft(next);
              }}
              onKeyDown={event => {
                if (event.key === 'Enter' && (event.ctrlKey || event.metaKey) && !event.nativeEvent.isComposing) {
                  event.preventDefault();
                  send();
                }
              }}
            />
          </div>
          <button
            type="button"
            disabled={!busy && (!available || !draft.trim())}
            onClick={() => {
              if (!busy) {
                send();
                return;
              }
              try {
                clickTavernStop();
                setError('');
              } catch (reason) {
                setError(reason instanceof Error ? reason.message : '无法中止生成，请检查酒馆。');
              }
            }}
            title={busy ? '中止生成' : '发送（Ctrl / ⌘ + Enter）'}
            aria-label={busy ? '中止生成' : '发送消息'}
          >
            {busy ? (
              <span aria-hidden="true" style={{ width: 14, height: 14, borderRadius: 3, background: 'currentColor' }} />
            ) : (
              <Send size={19} />
            )}
          </button>
        </div>
        {error && (
          <div className="campus-tablet-composer-note">
            <span role="alert">{error}</span>
          </div>
        )}
      </footer>
      {detail && (
        <div className="campus-tablet-modal" onClick={() => setDetail(null)}>
          <div
            role="dialog"
            aria-modal="true"
            aria-label="事项详情"
            tabIndex={-1}
            onKeyDown={event => {
              if (event.key === 'Escape') setDetail(null);
            }}
            onClick={event => event.stopPropagation()}
          >
            <header>
              <strong>事项详情</strong>
              <button autoFocus type="button" onClick={() => setDetail(null)} aria-label="关闭详情">
                <X size={18} />
              </button>
            </header>
            <div>
              {detail.map((item, index) => (
                <div key={index} className="campus-tablet-preview">
                  <h3>
                    {item.office} · {item.title}
                  </h3>
                  <strong>{item.subject}</strong>
                  <dl>
                    {item.fields.map(([label, value], fieldIndex) => (
                      <div key={fieldIndex}>
                        <dt>{label}</dt>
                        <dd>{value}</dd>
                      </div>
                    ))}
                  </dl>
                  <div className="campus-tablet-operation-actions">
                    <button
                      type="button"
                      disabled={busy}
                      onClick={() => {
                        const index = parts.findIndex(
                          part => part.type === 'document' && part.document.raw === item.raw,
                        );
                        if (index >= 0) setEditing({ index, original: parts[index].raw, value: parts[index].raw });
                      }}
                    >
                      编辑
                    </button>
                    <button
                      type="button"
                      disabled={busy}
                      onClick={() => {
                        const index = parts.findIndex(
                          part => part.type === 'document' && part.document.raw === item.raw,
                        );
                        if (index >= 0) {
                          updateOperation(index, parts[index].raw, '');
                          setDetail(null);
                        }
                      }}
                    >
                      删除
                    </button>
                  </div>
                  <details>
                    <summary>查看完整内容</summary>
                    <p>{item.raw}</p>
                  </details>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
      {editing && (
        <div className="campus-tablet-modal campus-tablet-editor">
          <div
            role="dialog"
            aria-modal="true"
            aria-label="编辑待发送操作"
            onKeyDown={event => {
              if (event.key === 'Escape') setEditing(null);
            }}
          >
            <header>
              <strong>编辑待发送操作</strong>
              <button type="button" onClick={() => setEditing(null)} aria-label="关闭编辑">
                <X size={18} />
              </button>
            </header>
            <div>
              <label htmlFor="campus-operation-editor">操作内容</label>
              <textarea
                id="campus-operation-editor"
                autoFocus
                value={editing.value}
                onChange={event => setEditing({ ...editing, value: event.target.value })}
              />
              <p>保留原有句式可继续显示为操作标签；其他内容会回到正文输入栏。</p>
              <div className="campus-tablet-operation-actions">
                <button type="button" onClick={() => setEditing(null)}>
                  取消
                </button>
                <button
                  type="button"
                  disabled={busy || !editing.value.trim()}
                  onClick={() => {
                    updateOperation(editing.index, editing.original, editing.value);
                    setDetail(null);
                  }}
                >
                  保存
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}
