export function getWorldbookManifest(): ManifestEntry[] {
  const configs = [...coreWorldbookEntries, ...variableWorldbookEntries];
  const characters: Record<string, { keys: string[]; order: number }> = characterWorldbookConfigs;
  const result: ManifestEntry[] = WORLD_BOOK_RELEASES.map(release => {
    const config =
      configs.find(entry => entry.name === release.name) ??
      (characters[release.name]
        ? createCharacterEntry(release.name, release.content, characters[release.name])
        : undefined);
    if (!config) throw new Error(`世界书清单缺少条目配置：${release.name}`);
    const defaultEnabled = release.name !== '校园论坛输出规则' && release.name !== '校园论坛更新需求';
    return {
      ...release,
      defaultEnabled,
      policy: release.id.startsWith('runtime.') ? 'runtime' : 'managed',
      entry: { ...config, name: release.name, content: release.content, enabled: defaultEnabled } as Omit<
        WorldbookEntry,
        'uid'
      >,
    };
  });
  result.push(
    ...[
      { id: 'runtime.player', name: 'user_玩家档案', source: '游戏开局/playerArchive.ts' },
      { id: 'runtime.initvar', name: '[initvar]变量初始化勿开', source: '变量世界书/[initvar]变量初始化勿开.yaml' },
    ].map(item => ({
      ...item,
      version: '1.0.0',
      policy: 'runtime' as const,
      defaultEnabled: item.id !== 'runtime.initvar',
    })),
  );
  return result;
}
