import { StrictMode, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { PhoneSimulator } from './状态栏/src/components/PhoneSimulator';
import { OpeningFlow } from './游戏开局/OpeningFlow';
import { FloatingPhoneHost, restoreCampusFrame } from './游戏开局/FloatingPhoneHost';
import {
  writeEnrollmentArchivesToWorldbook,
} from './游戏开局/playerArchive';
import { sendOpeningPrompt } from './游戏开局/openingPrompt';
import { CustomStartForm } from './游戏开局/constants';
import { registerCampusArraySchemaRepair } from './游戏开局/campusLocations';
import './index.css';
import $ from 'jquery';

function getCurrentFloor(): number {
  try {
    const frame = window.frameElement as HTMLIFrameElement | null;
    if (frame?.dataset.campusScriptMounted === '1' || /TH-script/i.test(frame?.id || '')) {
      return typeof getLastMessageId === 'function' ? getLastMessageId() : 0;
    }
    if (typeof getCurrentMessageId === 'function') {
      return getCurrentMessageId();
    }
  } catch (error) {
    console.warn('[校园APP] 无法读取当前楼层，按 0 层处理:', error);
  }
  return 0;
}

function CampusApp() {
  const floor = useMemo(() => getCurrentFloor(), []);
  const [enrolled, setEnrolled] = useState(false);

  const handleEnroll = async (form: CustomStartForm) => {
    const ok = await writeEnrollmentArchivesToWorldbook(form);
    if (!ok) return;
    setEnrolled(true);
    await sendOpeningPrompt(form);
  };

  if (floor === 0 && !enrolled) {
    return <OpeningFlow onEnroll={form => void handleEnroll(form)} />;
  }

  return <PhoneSimulator />;
}

$(async () => {
  console.info('[校园APP] 等待 MVU 框架初始化...');
  await waitGlobalInitialized('Mvu');
  console.info('[校园APP] MVU 框架已初始化');
  registerCampusArraySchemaRepair();

  const initApp = () => {
    const rootElement = document.getElementById('root');
    if (!rootElement) {
      console.error('[校园APP] Root element not found');
      return;
    }

    createRoot(rootElement).render(
      <StrictMode>
        <FloatingPhoneHost>
          <CampusApp />
        </FloatingPhoneHost>
      </StrictMode>,
    );

    console.info('[校园APP] 已加载');
  };

  initApp();
});

$(window).on('pagehide', () => {
  restoreCampusFrame();
  console.info('[校园APP] 已卸载');
});