import { setMvuVariable } from '../状态栏/src/hooks/useMvuData';
import { getActivityById, parseActivityForm } from './activities';
import { parseRoleArchiveForm, parseRoleArchiveName } from './classmates';
import { CustomStartForm } from './constants';

function trimText(value: string, fallback = '未填写'): string {
  const text = value.replace(/\s+/g, ' ').trim();
  return text || fallback;
}

function buildSelectedClassmateBriefs(form: CustomStartForm): string {
  const briefs: string[] = [];

  for (const entryName of form.selectedClassmateNames || []) {
    const content = form.classmateEdits?.[entryName];
    const parsedName = parseRoleArchiveName(entryName)?.character || entryName;
    if (!content) {
      briefs.push(`- ${parsedName}（已选择，档案内容待读取）`);
      continue;
    }
    const formData = parseRoleArchiveForm(content, parsedName);
    briefs.push(
      [
        `- ${formData.name || parsedName}`,
        `  性别：${trimText(formData.gender)}`,
        `  年龄：${trimText(formData.age)}`,
        `  身份：${trimText(formData.identities.filter(Boolean).join(' / ') || formData.relation)}`,
        `  关系：${trimText(formData.relation)}`,
        `  外貌要点：${trimText([formData.temperament, formData.hairStyle, formData.eyes].filter(Boolean).join('；'), '未补充')}`,
        `  性格要点：${trimText(
          formData.personalityTraits
            .map(item => item.name)
            .filter(Boolean)
            .join('、'),
          '未补充',
        )}`,
      ].join('\n'),
    );
  }

  for (const custom of form.customClassmates || []) {
    const formData = parseRoleArchiveForm(custom.content || '', custom.name || '自定义角色');
    briefs.push(
      [
        `- ${formData.name || custom.name || '自定义角色'}（自定义）`,
        `  性别：${trimText(formData.gender)}`,
        `  年龄：${trimText(formData.age)}`,
        `  身份：${trimText(formData.identities.filter(Boolean).join(' / '))}`,
        `  关系：${trimText(formData.relation)}`,
      ].join('\n'),
    );
  }

  return briefs.length ? briefs.join('\n') : '- 暂无已选角色';
}

function formatSessionBrief(session: { title: string; time: string; content: string }, index: number): string {
  const title = trimText(session.title, `环节${index + 1}`);
  const time = trimText(session.time, '时间未写明，请写成X月X日 时:分-X月X日 时:分');
  const content = trimText(session.content, '（暂无环节说明）');
  return `   环节${index + 1}：${title}｜${time}｜${content}`;
}

function formatActivities(form: CustomStartForm): string {
  const selected = form.selectedActivityNames || [];
  if (!selected.length) {
    return '未选择校园活动。开篇不要凭空写入建筑活动。';
  }

  return selected
    .map((entryName, index) => {
      const stored = getActivityById(entryName);
      const content = form.activityEdits?.[entryName] ?? stored?.content ?? '';
      const parsedName = stored?.displayName || entryName;
      const activity = parseActivityForm(content, parsedName);
      const sessions = activity.sessions.filter(
        session => session.title.trim() || session.time.trim() || session.content.trim(),
      );
      return [
        `${index + 1}. ${trimText(activity.name, parsedName)}`,
        `   活动地点：${trimText(activity.location, '未指定地点，请匹配一个已有校园建筑')}`,
        `   活动时间：${trimText(activity.time, '时间未写明，请写成X月X日 时:分-X月X日 时:分')}`,
        ...(sessions.length
          ? sessions.map((session, sessionIndex) => formatSessionBrief(session, sessionIndex))
          : ['   活动环节：无明确环节，可只写整场活动的起止时间']),
      ].join('\n');
    })
    .join('\n');
}

export function buildOpeningPrompt(form: CustomStartForm): string {
  const identity = form.identityDescription.trim()
    ? `${trimText(form.identityName)}。${trimText(form.identityDescription)}`
    : trimText(form.identityName);

  return [
    '【开篇请求】请根据以下入学档案信息，为当前校园故事撰写开场：',
    '',
    '玩家档案：',
    `- 姓名：${trimText(form.name)}`,
    `- 年龄：${trimText(form.age)}`,
    `- 相貌：${trimText(form.appearance)}`,
    `- 性格：${trimText(form.personality)}`,
    `- 身份：${identity}`,
    form.grade.trim() ? `- 年级：${trimText(form.grade)}` : '',
    `- 开局时间：${form.startTime?.year || 2025}年${form.startTime?.month || 9}月${form.startTime?.day || 1}日 ${String(form.startTime?.hour ?? 12).padStart(2, '0')}:${String(form.startTime?.minute ?? 30).padStart(2, '0')}`,
    `- 当前选择前往：${trimText(form.startingLocation, '未指定地点')}`,
    '',
    '已选NPC角色：',
    buildSelectedClassmateBriefs(form),
    '备注：以上为玩家在入学档案中选定的可选角色。开篇剧情中无需全部登场，请根据当下场景与剧情需要，从中选择单个或多个角色自然植入即可。仅出场角色需要写入「角色」变量，且必须包含依据形象或性格生成的网名；好友位默认 false，除非开篇明确加好友，否则不要改成 true。',
    '预设校园活动：',
    formatActivities(form),
    '',
    '请以玩家选择前往的区域为起点，结合其身份、性格、已选角色、当前已生效校规与已选活动，自然展开故事开篇。',
    '要求：场景具体、节奏紧凑，并给出可供玩家立刻接续行动的当下情境。若已选活动与当前地点相关，可让活动痕迹出现在开场环境里，但不必把所有活动都写成正在发生。',
    '',
    '【MVU变量完整更新要求】',
    '当前初始变量中的「玩家」「角色」「聊天群组」为空壳，「校规」已预置。以下是供变量更新阶段使用的初始化要求；剧情阶段只演绎故事，不输出 MVU_UPDATE YAML、变量快照或变量更新命令。变量更新阶段依据入学档案与本轮剧情，通过世界书规定的唯一 <UpdateVariable> / <JSONPatch> 格式补齐变量：',
    '1) 玩家：必须完整写入姓名、身份、班级、年龄、当前所在地、当前穿搭（上装/下装/内衣/配饰/鞋子）。',
    '2) 角色：为出场的NPC建立完整角色对象；仅出场角色需要建立。好友位默认 false，只有开篇明确加好友才可写成 true。',
    '3) 校规：不要重建、覆盖或清空已有校规。校规路径是「校规/分类/标题」，例如「校规/生活纪律/着装规范」。除非玩家明确要求，否则不要改写现有分类下的标题条目；若必须更新，只能改对应条目的内容/是否启用/生效地点。',
    '4) 聊天群组：只有开篇剧情里{{user}}明确进群、加入群聊或被拉进群时，才允许建立群组。字段包括群名、简介、成员；成员是角色网名，必须包含玩家。不要因为同班/同宿舍就提前建群。不要把聊天正文写入变量。给已有群追加成员时，必须 _.set 完整成员列表，不要对「成员」做 insert 或 /成员/-。',
    '5) 校园建筑.建筑活动：把上面「预设校园活动」全部写入对应建筑的「建筑活动」。不要改建筑坐标、类型或名称；地点必须使用已有建筑名。每个活动写入活动名称、开始时间、结束时间、活动描述；有环节时再写入活动环节（环节名称、开始时间、结束时间、环节描述）。时间字段只用月/日/小时/分钟数字。',
    '6) 时间：必须保持对象结构（年/月/日/小时/分钟/星期，全是数字）。禁止把「时间」整段替换成「2026年3月2日 12:40」这种字符串；只改变化的数字字段。',
  ]
    .filter(Boolean)
    .join('\n');
}

export async function sendOpeningPrompt(form: CustomStartForm): Promise<void> {
  const prompt = buildOpeningPrompt(form);
  try {
    if (form.startingLocation.trim()) {
      await setMvuVariable('玩家.当前所在地', form.startingLocation.trim());
    }
    if (form.startTime) {
      const weekday = new Date(form.startTime.year, form.startTime.month - 1, form.startTime.day).getDay();
      await setMvuVariable('时间.年', form.startTime.year);
      await setMvuVariable('时间.月', form.startTime.month);
      await setMvuVariable('时间.日', form.startTime.day);
      await setMvuVariable('时间.小时', form.startTime.hour);
      await setMvuVariable('时间.分钟', form.startTime.minute);
      await setMvuVariable('时间.星期', weekday);
    }
    await createChatMessages([{ role: 'user', message: prompt }], { refresh: 'affected' });
    await triggerSlash('/trigger');
    console.info('[校园APP] 已发送开篇提示词并触发生成');
  } catch (error) {
    console.error('[校园APP] 发送开篇提示词失败:', error);
    toastr.error('开篇提示词发送失败，请检查控制台', '入学提示');
  }
}
