import React, { useRef, useState, PointerEvent, useEffect } from 'react';

const DRAG_THRESHOLD = 5;

export function useDraggableScroll<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const dragRef = useRef({
    active: false,
    hasDragged: false,
    startY: 0,
    startX: 0,
    scrollTop: 0,
    scrollLeft: 0,
  });
  const [isDragging, setIsDragging] = useState(false);

  const onPointerDown = (e: PointerEvent<T>) => {
    if (!ref.current) return;

    const target = e.target as HTMLElement | null;
    if (target?.closest('input, textarea, select, option, [contenteditable="true"]')) return;

    const noDrag = target?.closest('[data-no-drag-scroll]');
    if (noDrag && ref.current.contains(noDrag) && noDrag !== ref.current) return;

    if (e.pointerType === 'mouse' && e.button !== 0) return;

    dragRef.current = {
      active: true,
      hasDragged: false,
      startY: e.clientY,
      startX: e.clientX,
      scrollTop: ref.current.scrollTop,
      scrollLeft: ref.current.scrollLeft,
    };
    setIsDragging(true);
  };

  useEffect(() => {
    const handlePointerMove = (e: globalThis.PointerEvent) => {
      const drag = dragRef.current;
      if (!drag.active || !ref.current) return;

      const walkY = (e.clientY - drag.startY) * 1.5;
      const walkX = (e.clientX - drag.startX) * 1.5;

      if (Math.abs(walkY) <= DRAG_THRESHOLD && Math.abs(walkX) <= DRAG_THRESHOLD) return;

      drag.hasDragged = true;
      ref.current.scrollTop = drag.scrollTop - walkY;
      ref.current.scrollLeft = drag.scrollLeft - walkX;
    };

    const handlePointerUp = () => {
      const drag = dragRef.current;
      if (!drag.active) return;
      drag.active = false;
      setIsDragging(false);
      window.setTimeout(() => {
        drag.hasDragged = false;
      }, 50);
    };

    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
    window.addEventListener('pointercancel', handlePointerUp);
    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
      window.removeEventListener('pointercancel', handlePointerUp);
    };
  }, []);

  const onClickCapture = (e: React.MouseEvent<T> | React.TouchEvent<T>) => {
    if (dragRef.current.hasDragged) {
      e.stopPropagation();
      if ('preventDefault' in e && e.cancelable !== false) {
        e.preventDefault();
      }
    }
  };

  return {
    ref,
    onPointerDown,
    onClickCapture,
    style: { cursor: isDragging ? 'grabbing' : 'auto' }
  };
}
