import { Sparkles, User } from 'lucide-react';
import { Card } from '../状态栏/src/components/ui/Card';
import { NamedTraitGroup, RoleArchiveForm } from './classmates';

function filled(values: string[]): string[] {
  return values.map(item => item.trim()).filter(Boolean);
}

function SubItemCard({ label, value }: { label: string; value: string }) {
  if (!value.trim()) return null;
  return (
    <div className="bg-surface rounded-xl p-3 border border-border-default shadow-sm flex flex-col gap-1">
      <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">{label}</span>
      <span className="text-xs text-text-primary font-medium leading-relaxed whitespace-pre-wrap">{value}</span>
    </div>
  );
}

function TraitReadView({ groups }: { groups: NamedTraitGroup[] }) {
  const valid = groups.filter(
    group =>
      group.name.trim() ||
      filled(group.manifestations).length ||
      (group.stages || []).some(stage => stage.name.trim() || filled(stage.items).length),
  );
  if (!valid.length) return null;
  return (
    <div className="flex flex-col gap-3">
      {valid.map(group => (
        <div key={group.id} className="bg-surface rounded-xl p-3 border border-border-default shadow-sm">
          {group.name.trim() && <p className="text-xs font-bold text-text-primary mb-2">{group.name}</p>}
          {filled(group.manifestations).length > 0 && (
            <div className="space-y-1.5 mb-2">
              {filled(group.manifestations).map((item, index) => (
                <p key={`${group.id}-item-${index}`} className="text-xs text-text-primary leading-relaxed">
                  {item}
                </p>
              ))}
            </div>
          )}
          {(group.stages || [])
            .filter(stage => stage.name.trim() || filled(stage.items).length)
            .map(stage => (
              <div key={stage.id} className="mt-2 rounded-xl bg-surface-solid border border-border-default p-2.5">
                {stage.name.trim() && <p className="text-[11px] font-bold text-text-primary mb-1.5">{stage.name}</p>}
                <div className="space-y-1">
                  {filled(stage.items).map((item, index) => (
                    <p key={`${stage.id}-${index}`} className="text-xs text-text-primary leading-relaxed">
                      {item}
                    </p>
                  ))}
                </div>
              </div>
            ))}
        </div>
      ))}
    </div>
  );
}

export function ClassmateDetailView({ form }: { form: RoleArchiveForm }) {
  const identities = filled(form.identities).join('、');
  const personalitySummary = filled(form.personalityTraits.map(item => item.name)).join('、');
  return (
    <div className="space-y-4">
      <div className="flex items-start gap-4 mb-2">
        <div className="w-[72px] h-[72px] rounded-3xl bg-surface flex items-center justify-center text-text-primary font-bold text-2xl shrink-0 border-2 border-border-default shadow-sm">
          {(form.name || '?').slice(0, 1)}
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-xl font-bold text-text-primary mb-2">{form.name || '未命名'}</h3>
          <div className="flex flex-col gap-2">
            {(personalitySummary || form.relation) && (
              <div className="flex items-center gap-1.5 soft-chip px-2 py-1 rounded-lg text-xs font-medium self-start">
                <Sparkles className="w-3 h-3" />
                <span className="truncate">{personalitySummary || form.relation}</span>
              </div>
            )}
            {identities && (
              <div className="flex items-center gap-1.5 soft-chip px-2 py-1 rounded-lg text-xs font-medium self-start">
                <User className="w-3 h-3" />
                <span className="truncate">{identities}</span>
              </div>
            )}
          </div>
        </div>
      </div>

      <Card>
        <p className="text-sm font-bold text-text-primary mb-3">基本信息</p>
        <div className="flex flex-col gap-2">
          <SubItemCard label="性别" value={form.gender} />
          <SubItemCard label="年龄" value={form.age} />
          <SubItemCard label="身份" value={identities} />
          <SubItemCard label={'与{{user}}关系'} value={form.relation} />
        </div>
      </Card>

      <Card>
        <p className="text-sm font-bold text-text-primary mb-3">外貌特征</p>
        <div className="flex flex-col gap-2">
          <SubItemCard label="身高" value={form.height} />
          <SubItemCard label="气质" value={form.temperament} />
          <SubItemCard label="发色" value={form.hairColor} />
          <SubItemCard label="发型" value={form.hairStyle} />
          <SubItemCard label="发饰" value={form.hairAccessory} />
          <SubItemCard label="眼睛" value={form.eyes} />
          <SubItemCard label="脸型" value={form.faceShape} />
          <SubItemCard label="胸部" value={form.chest} />
          <SubItemCard label="腰部" value={form.waist} />
          <SubItemCard label="腿部" value={form.legs} />
          <SubItemCard label="臀部" value={form.hips} />
          <SubItemCard label="上衣" value={form.top} />
          <SubItemCard label="下装" value={form.bottom} />
          <SubItemCard label="内衣" value={form.underwear} />
          <SubItemCard label="配饰" value={form.accessory} />
        </div>
      </Card>

      <Card>
        <p className="text-sm font-bold text-text-primary mb-3">核心特质</p>
        <TraitReadView groups={form.personalityTraits} />
      </Card>

      <Card>
        <p className="text-sm font-bold text-text-primary mb-3">NSFW_核心档案</p>
        <div className="flex flex-col gap-3">
          <TraitReadView groups={form.constitutions} />
          <SubItemCard label="小穴" value={form.pussy} />
          <SubItemCard label="后庭" value={form.anus} />
          <SubItemCard label="性癖取向" value={filled(form.fetishes).join('\n')} />
        </div>
      </Card>

      <Card>
        <p className="text-sm font-bold text-text-primary mb-3">语言特征</p>
        <div className="flex flex-col gap-2">
          <SubItemCard label="音色" value={form.voice} />
          <SubItemCard label="口癖" value={filled(form.catchphrases).join('\n')} />
          <SubItemCard label="情动时表现" value={filled(form.arousedBehaviors).join('\n')} />
        </div>
      </Card>

      <Card>
        <p className="text-sm font-bold text-text-primary mb-3">日常习惯</p>
        <div className="flex flex-col gap-2">
          {filled(form.habits).map((habit, index) => (
            <SubItemCard key={`${habit}-${index}`} label={`习惯${index + 1}`} value={habit} />
          ))}
        </div>
      </Card>
    </div>
  );
}
