import { Download, Hammer, Upload } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { setWorldbookEntryEnabled, upsertWorldbookArchives, deleteWorldbookEntries } from '../../../../游戏开局/playerArchive';
import { CampusBuilding, SchoolRule } from '../../types';
import { fillTavernInput } from '../../utils/fillTavernInput';
import { loadWorkshopCharacters } from '../../utils/workshopArchives';
import {
  downloadWorkshopPack,
  formatRulePrompt,
  fromWorkshopBuilding,
  fromWorkshopRule,
  parseWorkshopPack,
  toWorkshopBuilding,
  toWorkshopRule,
  uniqueRuleId,
  WORKSHOP_PACK_KIND,
  WORKSHOP_PACK_VERSION,
  WorkshopPack,
} from '../../utils/workshopPack';
import {
  downloadEnrollmentPack,
  buildEnrollmentPack,
  importEnrollmentPack,
  isEnrollmentPack,
  loadEnrollmentCatalog,
  parseEnrollmentPack,
  EnrollmentTab,
} from '../../utils/enrollmentWorkshop';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { FullScreenModal } from '../ui/Modal';
import { showToast } from '../ui/Toast';
import { EnrollmentWorkshopPanel } from './EnrollmentWorkshopPanel';
import { WorkshopExportModal } from './WorkshopExportModal';
import { ArchiveRow, ManageTab, WorkshopManagePanel } from './WorkshopManagePanel';

interface SettingsScreenProps {
  rules: SchoolRule[];
  buildings: CampusBuilding[];
  buildingTypes?: Record<string, string>;
  initialWorkshopModule?: 'world' | 'enrollment';
  onRulesImported: (rules: SchoolRule[]) => void;
  onBuildingsImported: (buildings: CampusBuilding[]) => void;
  onRulesDeleted: (ids: string[]) => void;
  onBuildingsDeleted: (ids: string[]) => void;
  onClose: () => void;
}

function buildingDetail(building: CampusBuilding, type?: string): string {
  const events = (building.events || []).map(event => `- ${event.name}${event.description ? `：${event.description}` : ''}`);
  return [
    type ? `建筑类型: ${type}` : '',
    building.description ? `建筑描述: ${building.description}` : '',
    `坐标: ${building.x}, ${building.y}`,
    `尺寸: ${building.width} x ${building.height}`,
    events.length ? `绑定活动:\n${events.join('\n')}` : '绑定活动: 无',
  ].filter(Boolean).join('\n');
}

export const SettingsScreen: React.FC<SettingsScreenProps> = ({
  rules,
  buildings,
  buildingTypes = {},
  initialWorkshopModule = 'world',
  onRulesImported,
  onBuildingsImported,
  onRulesDeleted,
  onBuildingsDeleted,
  onClose,
}) => {
  const fileRef = useRef<HTMLInputElement>(null);
  const enrollmentFileRef = useRef<HTMLInputElement>(null);
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const [manageTab, setManageTab] = useState<ManageTab>('rules');
  const [enrollmentTab, setEnrollmentTab] = useState<EnrollmentTab>('campus');
  const [exportOpen, setExportOpen] = useState(false);
  const [enrollmentExportOpen, setEnrollmentExportOpen] = useState(false);
  const [fileName, setFileName] = useState('圣樱工坊');
  const [enrollmentFileName, setEnrollmentFileName] = useState('入学档案工坊');
  const [selectedRuleIds, setSelectedRuleIds] = useState<string[]>([]);
  const [selectedCharacterNames, setSelectedCharacterNames] = useState<string[]>([]);
  const [selectedBuildingIds, setSelectedBuildingIds] = useState<string[]>([]);
  const [selectedCampusTypeIds, setSelectedCampusTypeIds] = useState<string[]>([]);
  const [selectedAppearanceIds, setSelectedAppearanceIds] = useState<string[]>([]);
  const [selectedPersonalityIds, setSelectedPersonalityIds] = useState<string[]>([]);
  const [selectedIdentityIds, setSelectedIdentityIds] = useState<string[]>([]);
  const [enrollmentTick, setEnrollmentTick] = useState(0);
  const [characters, setCharacters] = useState<ArchiveRow[]>([]);
  const [characterContents, setCharacterContents] = useState<Record<string, string>>({});
  const [loadingArchives, setLoadingArchives] = useState(true);
  const [busy, setBusy] = useState(false);
  const [workshopModule, setWorkshopModule] = useState<'world' | 'enrollment'>(initialWorkshopModule);
  const mvuRules = useMemo(() => rules.filter(rule => rule.pendingAction !== 'add'), [rules]);
  const enrollmentCatalog = useMemo(() => loadEnrollmentCatalog(), [enrollmentTick]);
  const existingCategories = useMemo(
    () => [...new Set(mvuRules.map(item => item.category?.trim()).filter(Boolean) as string[])],
    [mvuRules],
  );
  const buildingRows = useMemo(
    () => buildings.map(item => ({
      name: item.id || item.name,
      displayName: item.name,
      extra: `${buildingTypes[item.name] || '校园建筑'} · ${item.events?.length || 0} 个绑定活动`,
      content: buildingDetail(item, buildingTypes[item.name]),
    })),
    [buildings, buildingTypes],
  );

  const refreshArchives = async () => {
    setLoadingArchives(true);
    try {
      const nextChars = await loadWorkshopCharacters();
      setCharacters(nextChars.map(item => ({
        name: item.name,
        enabled: item.enabled,
        displayName: item.displayName,
        extra: `${item.campusType} · ${item.identity}`,
        content: item.content,
      })));
      setCharacterContents(Object.fromEntries(nextChars.map(item => [item.name, item.content])));
    } finally {
      setLoadingArchives(false);
    }
  };

  useEffect(() => {
    void refreshArchives();
  }, []);

  const handleExport = () => {
    const pack: WorkshopPack = {
      kind: WORKSHOP_PACK_KIND,
      version: WORKSHOP_PACK_VERSION,
      name: fileName.trim() || '圣樱工坊',
      exportedAt: new Date().toISOString(),
      rules: mvuRules.filter(item => selectedRuleIds.includes(item.id)).map(toWorkshopRule),
      characters: characters.filter(item => selectedCharacterNames.includes(item.name)).map(item => ({
        name: item.name,
        content: characterContents[item.name] || item.content || '',
        enabled: item.enabled !== false,
        displayName: item.displayName,
      })),
      activities: [],
      buildings: buildings
        .filter(item => selectedBuildingIds.includes(item.id || item.name))
        .map(item => toWorkshopBuilding(item, buildingTypes[item.name])),
    };
    if (!pack.rules.length && !pack.characters.length && !pack.buildings.length) {
      showToast('请至少选择一项再导出', 'error');
      return;
    }
    downloadWorkshopPack(pack, fileName);
    setExportOpen(false);
    showToast('已导出工坊文件', 'success');
  };

  const handleImportFile = async (file: File) => {
    setBusy(true);
    try {
      const parsed = parseWorkshopPack(JSON.parse(await file.text()));
      const existingIds = new Set(mvuRules.map(item => item.id));
      const importedRules = parsed.rules.map(rule => {
        const id = uniqueRuleId(existingIds, rule.id || rule.title);
        existingIds.add(id);
        return fromWorkshopRule(rule, id);
      });
      const archives = parsed.characters.map(item => ({ name: item.name, content: item.content, enabled: item.enabled !== false }));
      const written = archives.length ? await upsertWorldbookArchives(archives) : 0;
      const importedBuildings = parsed.buildings.map(fromWorkshopBuilding).filter(item => item.name);
      if (importedRules.length) onRulesImported(importedRules);
      if (importedBuildings.length) onBuildingsImported(importedBuildings);
      await refreshArchives();
      showToast(
        `已导入校规 ${importedRules.length}、角色 ${parsed.characters.length}、建筑 ${importedBuildings.length}`,
        importedRules.length || written || importedBuildings.length ? 'success' : 'info',
      );
    } catch {
      showToast('JSON 文件无效，导入失败', 'error');
    } finally {
      setBusy(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const handleEnrollmentExport = () => {
    const pack = buildEnrollmentPack(enrollmentFileName, {
      campus: selectedCampusTypeIds,
      looks: selectedAppearanceIds,
      minds: selectedPersonalityIds,
      identities: selectedIdentityIds,
    });
    if (!pack.campusTypes.length && !pack.appearances.length && !pack.personalities.length && !pack.identities.length) {
      showToast('请至少选择一项再导出', 'error');
      return;
    }
    downloadEnrollmentPack(pack, enrollmentFileName);
    setEnrollmentExportOpen(false);
    showToast('已导出入学档案工坊文件', 'success');
  };

  const handleEnrollmentImport = async (file: File) => {
    setBusy(true);
    try {
      const raw = JSON.parse(await file.text());
      if (!isEnrollmentPack(raw)) {
        showToast('这不是入学档案工坊 JSON', 'error');
        return;
      }
      const result = importEnrollmentPack(parseEnrollmentPack(raw));
      setEnrollmentTick(prev => prev + 1);
      showToast(
        `已导入校园类型 ${result.campus}、相貌 ${result.looks}、性格 ${result.minds}、身份 ${result.identities}`,
        result.total ? 'success' : 'info',
      );
    } catch {
      showToast('JSON 文件无效，导入失败', 'error');
    } finally {
      setBusy(false);
      if (enrollmentFileRef.current) enrollmentFileRef.current.value = '';
    }
  };

  const toggleArchive = async (kind: 'characters', name: string, enabled: boolean) => {
    if (!(await setWorldbookEntryEnabled(name, enabled))) return;
    setCharacters(prev => prev.map(item => (item.name === name ? { ...item, enabled } : item)));
  };

  const sendRule = (rule: SchoolRule) => {
    const ok = fillTavernInput(formatRulePrompt(rule, existingCategories));
    showToast(ok ? '已写入输入栏' : '写入输入栏失败', ok ? 'success' : 'error');
  };

  const handleDelete = async (kind: ManageTab, id: string) => {
    if (kind === 'rules') {
      onRulesDeleted([id]);
      showToast('已删除校规', 'success');
      return;
    }
    if (kind === 'buildings') {
      onBuildingsDeleted([id]);
      showToast('已删除建筑', 'success');
      return;
    }
    const removed = await deleteWorldbookEntries([id]);
    if (removed) {
      await refreshArchives();
      showToast('已删除世界书条目', 'success');
      return;
    }
    showToast('删除失败', 'error');
  };

  return (
    <FullScreenModal isOpen={true} onClose={onClose}>
      <div className="flex-1 flex flex-col min-h-0">
        <div className="px-6 py-4 shrink-0 border-b border-border-default/30">
          <h2 className="text-xl font-bold text-text-primary flex items-center gap-2">
            <Hammer className="w-6 h-6 text-amber-500" />
            工坊
          </h2>
        </div>
        <div
          className="flex-1 min-h-0 overflow-y-auto overflow-x-hidden p-5 pb-6 space-y-5 hide-scrollbar relative select-none cursor-grab active:cursor-grabbing touch-none"
          {...dragProps}
          ref={dragProps.ref}
        >
          <div className="grid grid-cols-2 gap-1 p-1 rounded-2xl bg-surface border border-border-default">
            <button
              type="button"
              onClick={() => setWorkshopModule('world')}
              className={`py-2 rounded-xl text-xs font-bold ${workshopModule === 'world' ? 'bg-surface-solid text-[color:var(--action-text)] shadow-sm' : 'text-text-secondary hover-fill'}`}
            >
              世界书工坊
            </button>
            <button
              type="button"
              onClick={() => setWorkshopModule('enrollment')}
              className={`py-2 rounded-xl text-xs font-bold ${workshopModule === 'enrollment' ? 'bg-surface-solid text-[color:var(--action-text)] shadow-sm' : 'text-text-secondary hover-fill'}`}
            >
              入学档案工坊
            </button>
          </div>

          {workshopModule === 'world' && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => {
                    setSelectedRuleIds(mvuRules.map(item => item.id));
                    setSelectedCharacterNames(characters.map(item => item.name));
                    setSelectedBuildingIds(buildings.map(item => item.id || item.name));
                    setFileName('圣樱工坊');
                    setExportOpen(true);
                  }}
                  className="rounded-2xl bg-surface-solid border border-border-default p-4 text-left shadow-sm hover-fill"
                >
                  <Download className="w-5 h-5 text-sky-500 mb-2" />
                  <div className="font-bold text-text-primary">导出</div>
                  <div className="text-[11px] text-text-secondary mt-1 leading-relaxed">多选校规、角色、建筑，导出 JSON</div>
                </button>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => fileRef.current?.click()}
                  className="rounded-2xl bg-surface-solid border border-border-default p-4 text-left shadow-sm disabled:opacity-60 hover-fill"
                >
                  <Upload className="w-5 h-5 text-emerald-500 mb-2" />
                  <div className="font-bold text-text-primary">导入</div>
                  <div className="text-[11px] text-text-secondary mt-1 leading-relaxed">上传 JSON，写入前端和世界书</div>
                </button>
              </div>
              <input
                ref={fileRef}
                type="file"
                accept="application/json,.json"
                className="hidden"
                onChange={event => {
                  const file = event.target.files?.[0];
                  if (file) void handleImportFile(file);
                }}
              />
              <WorkshopManagePanel
                tab={manageTab}
                onTabChange={setManageTab}
                rules={mvuRules}
                characters={characters}
                buildings={buildingRows}
                loading={loadingArchives}
                onArchiveToggle={(kind, name, enabled) => void toggleArchive(kind, name, enabled)}
                onSendRule={sendRule}
                onDelete={(kind, id) => void handleDelete(kind, id)}
              />
            </>
          )}

          {workshopModule === 'enrollment' && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => {
                    setSelectedCampusTypeIds(enrollmentCatalog.campusTypes.map(item => item.id));
                    setSelectedAppearanceIds(enrollmentCatalog.appearances.map(item => item.id));
                    setSelectedPersonalityIds(enrollmentCatalog.personalities.map(item => item.id));
                    setSelectedIdentityIds(enrollmentCatalog.identities.map(item => item.id));
                    setEnrollmentFileName('入学档案工坊');
                    setEnrollmentExportOpen(true);
                  }}
                  className="rounded-2xl bg-surface-solid border border-border-default p-4 text-left shadow-sm hover-fill"
                >
                  <Download className="w-5 h-5 text-sky-500 mb-2" />
                  <div className="font-bold text-text-primary">导出</div>
                  <div className="text-[11px] text-text-secondary mt-1 leading-relaxed">多选校园类型、相貌、性格、身份，导出 JSON</div>
                </button>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => enrollmentFileRef.current?.click()}
                  className="rounded-2xl bg-surface-solid border border-border-default p-4 text-left shadow-sm disabled:opacity-60 hover-fill"
                >
                  <Upload className="w-5 h-5 text-emerald-500 mb-2" />
                  <div className="font-bold text-text-primary">导入</div>
                  <div className="text-[11px] text-text-secondary mt-1 leading-relaxed">上传 JSON，写入自定义入学内容</div>
                </button>
              </div>
              <input
                ref={enrollmentFileRef}
                type="file"
                accept="application/json,.json"
                className="hidden"
                onChange={event => {
                  const file = event.target.files?.[0];
                  if (file) void handleEnrollmentImport(file);
                }}
              />
              <EnrollmentWorkshopPanel
                tab={enrollmentTab}
                onTabChange={setEnrollmentTab}
                tick={enrollmentTick}
                onChanged={() => setEnrollmentTick(prev => prev + 1)}
              />
            </>
          )}
        </div>
      </div>
      <WorkshopExportModal
        open={exportOpen}
        fileName={fileName}
        sections={[
          { id: 'rules', title: '校规', items: mvuRules.map(item => ({ id: item.id, label: item.title, extra: item.category || '其他' })), selected: selectedRuleIds, setSelected: setSelectedRuleIds },
          { id: 'characters', title: '角色', items: characters.map(item => ({ id: item.name, label: item.displayName || item.name, extra: item.extra })), selected: selectedCharacterNames, setSelected: setSelectedCharacterNames },
          { id: 'buildings', title: '建筑', items: buildingRows.map(item => ({ id: item.name, label: item.displayName || item.name, extra: item.extra })), selected: selectedBuildingIds, setSelected: setSelectedBuildingIds },
        ]}
        onFileNameChange={setFileName}
        onClose={() => setExportOpen(false)}
        onExport={handleExport}
      />
      <WorkshopExportModal
        open={enrollmentExportOpen}
        fileName={enrollmentFileName}
        sections={[
          { id: 'campus', title: '校园类型', items: enrollmentCatalog.campusTypes.map(item => ({ id: item.id, label: item.label, extra: item.extra })), selected: selectedCampusTypeIds, setSelected: setSelectedCampusTypeIds },
          { id: 'looks', title: '相貌', items: enrollmentCatalog.appearances.map(item => ({ id: item.id, label: item.label, extra: item.extra })), selected: selectedAppearanceIds, setSelected: setSelectedAppearanceIds },
          { id: 'minds', title: '性格', items: enrollmentCatalog.personalities.map(item => ({ id: item.id, label: item.label, extra: item.extra })), selected: selectedPersonalityIds, setSelected: setSelectedPersonalityIds },
          { id: 'identities', title: '身份', items: enrollmentCatalog.identities.map(item => ({ id: item.id, label: item.label, extra: item.extra })), selected: selectedIdentityIds, setSelected: setSelectedIdentityIds },
        ]}
        onFileNameChange={setEnrollmentFileName}
        onClose={() => setEnrollmentExportOpen(false)}
        onExport={handleEnrollmentExport}
      />
    </FullScreenModal>
  );
};
